import "testing"

func newDispatcherTestWebsocketClient(name string) *WebsocketClient {
	return &WebsocketClient{
		hostIP:   "127.0.0.1",
		hostPort: "12345",
		BaseClient: &BaseClient{
			broadcastChan: make(chan []byte, 1),
			name:          name,
			subType:       SubTypeFull,
		},
	}
}

func TestDispatcherRegisterClientTwice(t *testing.T) {
	d := &Dispatcher{}
	client := newDispatcherTestWebsocketClient("client-1")

	d.RegisterClient(client)
	d.RegisterClient(client)

	if got := len(d.clients); got != 1 {
		t.Fatalf("expected 1 registered client after duplicate register, got %d", got)
	}
}

func TestDispatcherUnregisterWebsocketClient(t *testing.T) {
	d := &Dispatcher{}
	client := newDispatcherTestWebsocketClient("client-1")

	d.RegisterClient(client)
	if got := len(d.clients); got != 1 {
		t.Fatalf("expected 1 registered client, got %d", got)
	}

	d.UnregisterClient(client)
	if got := len(d.clients); got != 0 {
		t.Fatalf("expected 0 registered clients after unregister, got %d", got)
	}
}

func TestDispatcherUnregisterWebsocketClientDoesNotPanicOnNilStopChan(t *testing.T) {
	d := &Dispatcher{}
	client := newDispatcherTestWebsocketClient("client-2")

	d.RegisterClient(client)

	defer func() {
		if r := recover(); r != nil {
			t.Fatalf("unregistering websocket client panicked: %v", r)
		}
	}()

	d.UnregisterClient(client)
}

package broadcast

import (
	"context"
	"errors"
	"log"
	"net"
	"time"

	"github.com/d-Rickyy-b/certstream-server-go/internal/backoff"
	"github.com/segmentio/kafka-go"
)

var (
	kafkaMaxBatchSize = 50
	kafkaMaxBatchWait = 1 * time.Second
	kafkaConnTimeout  = 5 * time.Second
)

// KafkaClient connects to a Kafka server in order to provide it with certificates.
type KafkaClient struct {
	conn        *kafka.Conn // Kafka connection
	addr        string
	topic       string
	compression kafka.Compression
	isConnected bool
	BaseClient
}

// NewKafkaClient creates a new Kafka client that immediately connects to the configured Kafka server.
func NewKafkaClient(subType SubscriptionType, addr, name, topic, compression string, certBufferSize int) *KafkaClient {
	// Connect to the Kafka server
	ctx, cancel := context.WithTimeout(context.Background(), kafkaConnTimeout)
	defer cancel()
	conn, err := kafka.DialLeader(ctx, "tcp", addr, topic, 0)
	if err != nil {
		log.Println("failed to connect to kafka:", err)
	}
	// TODO implement explicit topic creation

	kc := &KafkaClient{
		conn:  conn,
		addr:  addr,
		topic: topic,
		BaseClient: BaseClient{
			broadcastChan: make(chan []byte, certBufferSize),
			stopChan:      make(chan struct{}),
			name:          name,
			subType:       subType,
		},
	}

	var kafkaCompression kafka.Compression
	switch compression {
	case "gzip":
		kafkaCompression = kafka.Gzip
	case "snappy":
		kafkaCompression = kafka.Snappy
	case "lz4":
		kafkaCompression = kafka.Lz4
	case "none", "":
	default:
		log.Println("invalid compression type:", compression)
	}

	kc.compression = kafkaCompression

	go kc.broadcastHandler()
	go kc.reconnectHandler()

	return kc
}

// reconnectHandler is a background job that attempts to reconnect to the Kafka server if the connection is lost.
func (c *KafkaClient) reconnectHandler() {
	for {
		select {
		case <-c.stopChan:
			log.Println("Stopping reconnectHandler for kafka producer:", c.addr)
			c.conn.Close()

			return
		default:
			if c.isConnected {
				// If already connected or no connection exists, skip reconnection
				time.Sleep(5 * time.Second)
				continue
			}

			// Attempt to connect to the Kafka server
			ctx, cancel := context.WithTimeout(context.Background(), kafkaConnTimeout)
			defer cancel()
			conn, err := kafka.DialLeader(ctx, "tcp", c.addr, c.topic, 0)
			if err != nil {
				log.Printf("Reconnect failed: %v. Retrying in 5s...", err)
				time.Sleep(5 * time.Second)

				continue
			}
			// Close old connection if exists
			if c.conn != nil {
				_ = c.conn.Close()
			}

			c.conn = conn
			c.isConnected = true
			log.Println("Reconnected to Kafka at", c.addr)
		}
	}
}

// Each client has a broadcastHandler that runs in the background and sends out the broadcast messages to the client.
func (c *KafkaClient) broadcastHandler() {
	defer func() {
		log.Println("Closing broadcast handler for kafka producer:", c.addr)
		if c.conn != nil {
			if err := c.conn.Close(); err != nil {
				log.Println("failed to close conn:", err)
				return
			}
		}

		ClientHandler.UnregisterClient(c)
	}()

	backoffHandler := backoff.NewBackoff(60 * time.Second)
	batch := make([]kafka.Message, 0, kafkaMaxBatchSize)
	t := time.NewTimer(kafkaMaxBatchWait)

	for {
		select {
		case <-c.stopChan:
			return
		case message, ok := <-c.broadcastChan:
			if !ok {
				log.Println("broadcastChan closed for kafkaClient:", c.addr)
				return
			}

			// Drop messages if not connected
			if !c.isConnected {
				time.Sleep(5 * time.Second)
				continue
			}

			msg := kafka.Message{Value: message}
			batch = append(batch, msg)

			// Write batch if it reaches max size
			if len(batch) >= kafkaMaxBatchSize {
				err := c.writeBatch(batch)
				if err != nil {
					// Without using a backoff strategy, the errors would massively spam the log
					backoffHandler(func() {
						var netErr *net.OpError
						if errors.As(err, &netErr) {
							c.isConnected = false
						}

						log.Printf("Error writing messages to kafka: %v", err)
					})
				}

				batch = batch[:0]
				t.Reset(kafkaMaxBatchWait)
			}
		case <-t.C:
			// If batch size has not reached kafkaMaxBatchSize, write the batch after kafkaMaxBatchWait
			if len(batch) == 0 {
				continue
			}

			err := c.writeBatch(batch)
			if err != nil {
				// Without using a backoff strategy, the errors would massively spam the log
				backoffHandler(func() {
					var netErr *net.OpError
					if errors.As(err, &netErr) {
						c.isConnected = false
					}

					log.Printf("Error writing messages to kafka: %v", err)
				})
			}

			batch = batch[:0]
		}
	}
}

// writeBatch writes a batch of messages to Kafka, handling exponential backoff and connection state
func (c *KafkaClient) writeBatch(batch []kafka.Message) error {
	if len(batch) == 0 {
		return nil
	}

	if c.conn == nil || !c.isConnected {
		return errors.New("no connection to kafka")
	}

	_ = c.conn.SetWriteDeadline(time.Now().Add(kafkaConnTimeout))

	_, err := c.conn.WriteCompressedMessages(
		c.compression.Codec(),
		batch...,
	)
	if err != nil {
		// Treat kafka errors specially
		var kafkaErr kafka.Error
		if errors.As(err, &kafkaErr) {
			if errors.Is(kafkaErr, kafka.MessageSizeTooLarge) {
				log.Printf("Message size is too large for kafka broker '%s' - reducing batch size to %d", c.addr, kafkaMaxBatchSize/2)
				kafkaMaxBatchSize = kafkaMaxBatchSize / 2
				// TODO: currently there is no retry mechanism implemented. We should try to resend the current batch with the reduced batch size.
			}
		}

		return err
	}
	return nil
}

package broadcast

import (
	"log"
	"time"

	"github.com/nsqio/go-nsq"
)

const (
	nsqMaxBatchSize = 50
	nsqMaxBatchWait = 1 * time.Second
)

// NSQClient connects to a NSQ server in order to provide it with certificates.
type NSQClient struct {
	conn        *nsq.Producer // nsq connection
	addr        string
	topic       string
	isConnected bool
	BaseClient
}

// nullLogger is a logger that does not output anything.
// It is used to silence the NSQ logger.
type nullLogger struct{}

func (l nullLogger) Output(calldepth int, s string) error {
	// Do nothing, effectively silencing the logger
	return nil
}

// NewNSQClient creates a new NSQ client that immediately connects to the configured NSQ server
func NewNSQClient(subType SubscriptionType, addr, name, topic string, certBufferSize int) *NSQClient {
	log.Println("Initializing NSQ client...")

	// Instantiate a producer.
	conf := nsq.NewConfig()

	conn, err := nsq.NewProducer(addr, conf)
	if err != nil {
		log.Println(err)
	}

	log.Println("Connected to NSQ server at", addr)

	// Silence log output from NSQ
	conn.SetLogger(nullLogger{}, nsq.LogLevelError)

	nsqc := &NSQClient{
		conn:  conn,
		addr:  addr,
		topic: topic,
		BaseClient: BaseClient{
			broadcastChan: make(chan []byte, certBufferSize),
			stopChan:      make(chan struct{}),
			name:          name,
			subType:       subType,
		},
	}
	nsqc.isConnected = true

	go nsqc.broadcastHandler()
	go nsqc.reconnectHandler()

	return nsqc
}

// reconnectHandler is a background job that attempts to reconnect to the NSQ server if the connection is lost.
func (c *NSQClient) reconnectHandler() {
	for {
		select {
		case <-c.stopChan:
			log.Println("Stopping reconnectHandler for nsq producer:", c.addr)
			c.conn.Stop()

			return
		default:
			if c.isConnected {
				// If already connected or no connection exists, skip reconnection
				time.Sleep(5 * time.Second)
				continue
			}

			// Attempt to connect to the NSQ server
			err := c.conn.Ping()
			if err != nil {
				log.Printf("Reconnect to NSQ server failed: '%v'. Retrying in 5s...", err)
				time.Sleep(5 * time.Second)

				continue
			}

			c.isConnected = true
			log.Println("Reconnected to NSQ server at", c.addr)
		}
	}
}

// Each client has a broadcastHandler that runs in the background and sends out the broadcast messages to the client.
func (c *NSQClient) broadcastHandler() {
	defer func() {
		log.Println("Closing broadcast handler for nsq producer:", c.addr)
		if c.conn != nil {
			// Gracefully stop the producer when appropriate (e.g. before shutting down the service)
			c.conn.Stop()
		}

		ClientHandler.UnregisterClient(c)
	}()

	batch := make([][]byte, 0, nsqMaxBatchSize)
	t := time.NewTicker(nsqMaxBatchWait)

	for {
		select {
		case <-c.stopChan:
			return
		case message, ok := <-c.broadcastChan:
			if !ok {
				log.Println("broadcastChan closed for nsqClient:", c.addr)
				return
			}

			// Drop messages if not connected
			if !c.isConnected {
				time.Sleep(5 * time.Second)
				continue
			}

			batch = append(batch, message)

			// Write batch if it reaches max size
			if len(batch) >= nsqMaxBatchSize {
				err := c.writeBatch(batch)
				if err != nil {
					log.Println("Failed to write messages to NSQ:", err)
					c.isConnected = false
				}
				batch = batch[:0]
				t.Reset(kafkaMaxBatchWait)
			}
		case <-t.C:
			// If batch size has not reached nsqMaxBatchSize, write the batch after nsqMaxBatchWait
			if len(batch) == 0 {
				continue
			}

			err := c.writeBatch(batch)
			if err != nil {
				log.Println("Failed to write messages to NSQ:", err)
				c.isConnected = false
			}
			batch = batch[:0]
		}
	}
}

func (c *NSQClient) writeBatch(batch [][]byte) error {
	if len(batch) == 0 {
		return nil
	}

	// Synchronously publish a batch of messages to the specified topic.
	err := c.conn.MultiPublish(c.topic, batch)
	if err != nil {
		log.Println("Failed to write messages to NSQ:", err)
		c.isConnected = false
		return err
	}

	return nil
}

package broadcast

import (
	"fmt"
	"log"
	"math/rand"
	"net"
	"strings"
	"time"

	"github.com/gorilla/websocket"
)

const idChars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

// WebsocketClient represents a single WebSocket client's connection to the server.
type WebsocketClient struct {
	conn             *websocket.Conn
	userAgent        string
	hostIP           string
	hostPort         string
	realIPFromHeader string

	*BaseClient
}

// NewWebsocketClient creates a new WebSocket client from the given connection.
func NewWebsocketClient(conn *websocket.Conn, subType SubscriptionType, name, userAgent, hostIP, hostPort, realIPFromHeader string, certBufferSize int) *WebsocketClient {
	c := &WebsocketClient{
		conn:             conn,
		userAgent:        userAgent,
		hostIP:           hostIP,
		hostPort:         hostPort,
		realIPFromHeader: realIPFromHeader,
		BaseClient: &BaseClient{
			broadcastChan: make(chan []byte, certBufferSize),
			stopChan:      make(chan struct{}),
			name:          name,
			subType:       subType,
		},
	}
	go c.broadcastHandler()
	go c.listenWebsocket()

	return c
}

// generateClientID generates a random 8-char identifier for the client.
func generateClientID() string {
	clientID := make([]byte, 8)
	for i := range clientID {
		//nolint:gosec
		clientID[i] = idChars[rand.Intn(len(idChars))]
	}

	return string(clientID)
}

// Each client has a broadcastHandler that runs in the background and sends out the broadcast messages to the client.
func (c *WebsocketClient) broadcastHandler() {
	writeWait := 60 * time.Second
	pingTicker := time.NewTicker(30 * time.Second)

	defer func() {
		log.Println("Closing broadcast handler for client:", c.Name()) //nolint:gosec

		pingTicker.Stop()

		_ = c.conn.SetWriteDeadline(time.Now().Add(5 * time.Second))
		_ = c.conn.WriteMessage(websocket.CloseMessage, []byte{})
		_ = c.conn.Close()
	}()

	for {
		select {
		case <-pingTicker.C:
			_ = c.conn.SetWriteDeadline(time.Now().Add(writeWait))

			if err := c.conn.WriteMessage(websocket.PingMessage, nil); err != nil {
				return
			}
		case message := <-c.broadcastChan:
			_ = c.conn.SetWriteDeadline(time.Now().Add(writeWait))

			w, err := c.conn.NextWriter(websocket.TextMessage)
			if err != nil {
				log.Printf("Error while getting next writer: %v\n", err)
				return
			}

			_, writeErr := w.Write(message)
			if writeErr != nil {
				log.Printf("Error while writing: %v\n", writeErr)
			}

			if closeErr := w.Close(); closeErr != nil {
				log.Printf("Error while closing: %v\n", closeErr)
				return
			}
		}
	}
}

// listenWebsocket is running in the background on a goroutine and listens for messages from the client.
// It responds to ping messages with a pong message. It closes the connection if the client sends
// a close message or no ping is received within 65 seconds.
func (c *WebsocketClient) listenWebsocket() {
	defer func() {
		_ = c.conn.Close()
		ClientHandler.UnregisterClient(c)
	}()

	readWait := 65 * time.Second

	c.conn.SetReadLimit(512)
	_ = c.conn.SetReadDeadline(time.Now().Add(readWait))

	defaultPingHandler := c.conn.PingHandler()

	c.conn.SetPingHandler(func(appData string) error {
		// Ping received - reset the deadline
		err := c.conn.SetReadDeadline(time.Now().Add(readWait))
		if err != nil {
			return fmt.Errorf("error while setting read deadline: %w", err)
		}

		return defaultPingHandler(appData)
	})

	c.conn.SetPongHandler(func(string) error {
		// Pong received - reset the deadline
		err := c.conn.SetReadDeadline(time.Now().Add(readWait))
		if err != nil {
			return fmt.Errorf("error while setting read deadline: %w", err)
		}

		return nil
	})

	// Handle messages from the client
	for {
		// ignore any message sent from clients - we only handle errors (aka. disconnects)
		_, _, readErr := c.conn.ReadMessage()
		if readErr == nil {
			continue
		}

		if websocket.IsUnexpectedCloseError(readErr, websocket.CloseGoingAway, websocket.CloseNormalClosure) {
			log.Printf("Unexpected websocket close error: %v\n", readErr)
		}

		// If client fails to send ping messages
		if strings.Contains(strings.ToLower(readErr.Error()), "i/o timeout") {
			log.Printf("No ping received from client: %s\n", c.Name()) //nolint:gosec

			closeMessage := websocket.FormatCloseMessage(websocket.ClosePolicyViolation, "No ping received!")

			writeErr := c.conn.WriteControl(websocket.CloseMessage, closeMessage, time.Now().Add(5*time.Second))
			if writeErr != nil {
				log.Printf("Error while sending close message: %v\n", writeErr)
			}
		} else if strings.Contains(strings.ToLower(readErr.Error()), "an existing connection was forcibly closed by the remote host") {
			log.Printf("Connection to client lost: %s\n", c.Name()) //nolint:gosec
		}

		log.Printf("Disconnecting client %s!\n", c.Name()) //nolint:gosec

		break
	}
}

// sanitizeInput removes newline and carriage-return characters from a
// string to prevent log-injection attacks (gosec G706).
func sanitizeInput(s string) string {
	s = strings.ReplaceAll(s, "\n", "\\n")
	s = strings.ReplaceAll(s, "\r", "\\r")

	return s
}

// Name returns the name/identifier for this client.
func (c *WebsocketClient) Name() string {
	clientName := fmt.Sprintf("[%s] - ", c.name)

	realIP := sanitizeInput(c.realIPFromHeader)
	socket := net.JoinHostPort(c.hostIP, c.hostPort)

	// If the realIP is set and if it differs from the connection IP, return both the connection IP and the real IP.
	if realIP != "" && realIP != c.hostIP {
		clientName += fmt.Sprintf("%s (via %s)", socket, realIP)
	} else {
		clientName += socket
	}

	if c.userAgent != "" {
		ua := sanitizeInput(c.userAgent)
		clientName += fmt.Sprintf(" - '%s'", ua)
	}

	return clientName
}

package broadcast

import (
	"fmt"
	"testing"
)

func newTestClient(name, connectionIP, connectionPort, realIP, userAgent string) *WebsocketClient {
	c := &WebsocketClient{
		hostIP:           connectionIP,
		hostPort:         connectionPort,
		realIPFromHeader: realIP,
		userAgent:        userAgent,
		BaseClient:       &BaseClient{name: name},
	}
	return c
}

// TestClientName tests if the Name() function returns properly formatted names based on various client configurations.
func TestClientName(t *testing.T) {
	tests := []struct {
		name           string
		id             string
		connectionIP   string
		connectionPort string
		realIP         string
		userAgent      string
		want           string
	}{
		{
			name:           "connection IP only",
			id:             "M7hBCSxj",
			connectionIP:   "1.2.3.4",
			connectionPort: "1234",
			realIP:         "",
			userAgent:      "",
			want:           "[M7hBCSxj] - 1.2.3.4:1234",
		},
		{
			name:           "realIP same as connectionIP",
			id:             "Epdy7ZIl",
			connectionIP:   "1.2.3.4",
			connectionPort: "1234",
			realIP:         "1.2.3.4",
			userAgent:      "",
			want:           "[Epdy7ZIl] - 1.2.3.4:1234",
		},
		{
			name:           "realIP differs from connectionIP",
			id:             "4Y0NE9v0",
			connectionIP:   "10.0.0.1",
			connectionPort: "1234",
			realIP:         "203.0.113.5",
			userAgent:      "",
			want:           "[4Y0NE9v0] - 10.0.0.1:1234 (via 203.0.113.5)",
		},
		{
			name:           "with user agent",
			id:             "a32J8PW4",
			connectionIP:   "1.2.3.4",
			connectionPort: "1234",
			realIP:         "",
			userAgent:      "go-certstream/1.0",
			want:           "[a32J8PW4] - 1.2.3.4:1234 - 'go-certstream/1.0'",
		},
		{
			name:           "with user agent and proxy",
			id:             "qiBSXENv",
			connectionIP:   "10.0.0.1",
			connectionPort: "1234",
			realIP:         "203.0.113.5",
			userAgent:      "go-certstream/1.0",
			want:           "[qiBSXENv] - 10.0.0.1:1234 (via 203.0.113.5) - 'go-certstream/1.0'",
		},
		{
			name:           "user agent with newline is escaped",
			id:             "enf8k2HQ",
			connectionIP:   "1.2.3.4",
			connectionPort: "1234",
			realIP:         "",
			userAgent:      "bad\nagent",
			want:           "[enf8k2HQ] - 1.2.3.4:1234 - 'bad\\nagent'",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			c := newTestClient(tt.id, tt.connectionIP, tt.connectionPort, tt.realIP, tt.userAgent)
			got := c.Name()
			if got != tt.want {
				t.Errorf("Name() = %q, want %q", got, tt.want)
			}
		})
	}
}

// TestGenerateClientID tests if generating a client ID produces a string of the correct length and character set.
func TestGenerateClientID(t *testing.T) {
	id := generateClientID()
	if len(id) != 8 {
		t.Errorf("generateClientID() length = %d, want 8", len(id))
	}

	for _, ch := range id {
		if !isValidIDChar(ch) {
			t.Errorf("generateClientID() contains invalid character: %q", ch)
		}
	}
}

// TestGenerateClientIDUniqueness tests if there are collisions within 1000 generated IDs.
func TestGenerateClientIDUniqueness(t *testing.T) {
	const iterations = 1000
	seen := make(map[string]struct{}, iterations)

	for i := range iterations {
		id := generateClientID()
		if _, exists := seen[id]; exists {
			t.Logf("collision after %d iterations (non-fatal, low probability expected)", i)
		}
		seen[id] = struct{}{}
	}

	if len(seen) < iterations/2 {
		t.Errorf("too many collisions: only %d unique IDs out of %d", len(seen), iterations)
	}
}

func isValidIDChar(ch rune) bool {
	return (ch >= 'a' && ch <= 'z') ||
		(ch >= 'A' && ch <= 'Z') ||
		(ch >= '0' && ch <= '9')
}

// TestClientNameAlwaysContainsID tests if the id prefix is always present in the Name() output.
func TestClientNameAlwaysContainsID(t *testing.T) {
	c := newTestClient("TESTID1X", "5.6.7.8", "", "", "")
	got := c.Name()
	expected := fmt.Sprintf("[%s]", "TESTID1X")
	if len(got) < len(expected) || got[:len(expected)] != expected {
		t.Errorf("Name() %q does not start with id prefix %q", got, expected)
	}
}

package certificatetransparency

import (
	"context"
	"fmt"
	"io"
	"log"
	"net/http"
	"slices"
	"strings"
	"time"

	"github.com/d-Rickyy-b/certstream-server-go/internal/config"
	"github.com/google/certificate-transparency-go/loglist3"
)

var googleLogListFetcher = NewHTTPLogListFetcher(loglist3.LogListURL)

type LogListFetcher interface {
	Fetch() (loglist3.LogList, error)
}

type HTTPLogListFetcher struct {
	LogListURL string
}

func NewHTTPLogListFetcher(url string) *HTTPLogListFetcher {
	return &HTTPLogListFetcher{LogListURL: url}
}

// Fetch fetches the list of all CT logs from the provided LogList URL.
func (f *HTTPLogListFetcher) Fetch() (loglist3.LogList, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	httpClient := newHTTPClient()

	req, newReqErr := http.NewRequestWithContext(ctx, http.MethodGet, f.LogListURL, nil)
	if newReqErr != nil {
		return loglist3.LogList{}, fmt.Errorf("failed to create loglist request: %w", newReqErr)
	}

	// Download the list of all logs from ctLogInfo and decode JSON
	resp, reqErr := httpClient.Do(req)
	if reqErr != nil {
		return loglist3.LogList{}, fmt.Errorf("failed to execute loglist request: %w", reqErr)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return loglist3.LogList{}, fmt.Errorf("%w: unexpected status code %d", ErrRequestFailed, resp.StatusCode)
	}

	bodyBytes, readErr := io.ReadAll(resp.Body)
	if readErr != nil {
		return loglist3.LogList{}, fmt.Errorf("failed reading response body: %w", readErr)
	}

	allLogs, parseErr := loglist3.NewFromJSON(bodyBytes)
	if parseErr != nil {
		return loglist3.LogList{}, fmt.Errorf("failed parsing response body: %w", parseErr)
	}

	return *allLogs, nil
}

// getAllLogs returns a list of all CT logs - those from the Google list, if not disabled -
// and additional logs provided via the config.
func getAllLogs(logListFetcher LogListFetcher) (loglist3.LogList, error) {
	var allLogs loglist3.LogList
	excludedOperators := []string{}
	excludedLogs := []string{}

	// Extract excluded logs from the config.
	for _, excludedLog := range config.AppConfig.General.ExcludedLogs {
		if excludedLog.URL == "" {
			// Exclude whole operator
			excludedOperators = append(excludedOperators, excludedLog.Operator)
		} else {
			// Exclude only this specific URL (normalize for comparison)
			excludedLogs = append(excludedLogs, normalizeCtlogURL(excludedLog.URL))
		}
	}

	// Ability to disable default logs, if the user only wants to monitor custom logs.
	if !config.AppConfig.General.DisableDefaultLogs {
		var err error

		allLogs, err = logListFetcher.Fetch()
		if err != nil {
			log.Printf("Error fetching log list: %s\n", err)
			return loglist3.LogList{}, fmt.Errorf("failed to fetch log list: %w", err)
		}
	}

	// Add additional logs provided via the config, if any.
	for _, additionalLog := range config.AppConfig.General.AdditionalLogs {
		customLog := loglist3.Log{
			URL:         additionalLog.URL,
			Description: additionalLog.Description,
		}

		operatorFound := false

		for _, operator := range allLogs.Operators {
			// Only compare logs with the same operator
			if operator.Name != additionalLog.Operator {
				continue
			}

			operatorFound = true
			logFound := false

			// Check if user provided log is already in our loglist
			for _, ctlog := range operator.Logs {
				if ctlog.URL == additionalLog.URL {
					// Log already exists, skip it.
					logFound = true
					break
				}
			}

			if !logFound {
				// This works, since allLogs.Operators is a slice of pointers.
				operator.Logs = append(operator.Logs, &customLog)
			}

			break
		}

		if !operatorFound {
			newOperator := loglist3.Operator{
				Name: additionalLog.Operator,
				Logs: []*loglist3.Log{&customLog},
			}
			allLogs.Operators = append(allLogs.Operators, &newOperator)
		}
	}

	for _, additionalLog := range config.AppConfig.General.AdditionalTiledLogs {
		customLog := loglist3.TiledLog{
			MonitoringURL: additionalLog.URL,
			Description:   additionalLog.Description,
		}

		operatorFound := false

		for _, operator := range allLogs.Operators {
			if operator.Name != additionalLog.Operator {
				continue
			}

			operatorFound = true
			logFound := false

			for _, tl := range operator.TiledLogs {
				if tl.MonitoringURL == additionalLog.URL {
					// Log already exists, skip it.
					logFound = true
					break
				}
			}

			if !logFound {
				// This works, since allLogs.Operators is a slice of pointers.
				operator.TiledLogs = append(operator.TiledLogs, &customLog)
			}

			break
		}

		if !operatorFound {
			newOperator := loglist3.Operator{
				Name:      additionalLog.Operator,
				TiledLogs: []*loglist3.TiledLog{&customLog},
			}
			allLogs.Operators = append(allLogs.Operators, &newOperator)
		}
	}

	// Remove excluded operators and logs after we've added custom logs.
	if len(excludedOperators) > 0 || len(excludedLogs) > 0 {
		filteredOperators := []*loglist3.Operator{}

		for _, operator := range allLogs.Operators {
			// Skip whole operator if it's excluded
			if slices.Contains(excludedOperators, operator.Name) {
				continue
			}

			// Filter normal logs
			if len(operator.Logs) > 0 {
				keepLogs := []*loglist3.Log{}
				for _, l := range operator.Logs {
					if slices.Contains(excludedLogs, normalizeCtlogURL(l.URL)) {
						// excluded, skip
						log.Println("Excluding log based on the config: ", operator.Name, normalizeCtlogURL(l.URL))
						continue
					}

					keepLogs = append(keepLogs, l)
				}

				operator.Logs = keepLogs
			}

			// Filter tiled logs
			if len(operator.TiledLogs) > 0 {
				keepTiled := []*loglist3.TiledLog{}
				for _, tl := range operator.TiledLogs {
					if slices.Contains(excludedLogs, normalizeCtlogURL(tl.MonitoringURL)) {
						// excluded, skip
						log.Println("Excluding tiled log based on the config: ", operator.Name, normalizeCtlogURL(tl.MonitoringURL))
						continue
					}

					keepTiled = append(keepTiled, tl)
				}

				operator.TiledLogs = keepTiled
			}

			filteredOperators = append(filteredOperators, operator)
		}

		allLogs.Operators = filteredOperators
	}

	return allLogs, nil
}

func normalizeCtlogURL(input string) string {
	input = strings.TrimPrefix(input, "https://")
	input = strings.TrimPrefix(input, "http://")
	input = strings.TrimSuffix(input, "/")

	return input
}

