package certificatetransparency

import (
	"bytes"
	"crypto/sha1" //nolint:gosec
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"hash"
	"log"
	"math/big"
	"slices"
	"strings"
	"time"

	"github.com/d-Rickyy-b/certstream-server-go/internal/models"

	ct "github.com/google/certificate-transparency-go"
	"github.com/google/certificate-transparency-go/x509"
	"github.com/google/certificate-transparency-go/x509/pkix"
)

// parseData converts a *ct.RawLogEntry struct into a certstream.Data struct by copying some values and calculating others.
func parseData(entry *ct.RawLogEntry, operatorName, logName, ctURL, logType string) (models.Data, error) {
	var certLink string
	// There is no direct link for tiled ct logs
	if logType == models.SourceIsRFC6962 {
		certLink = fmt.Sprintf("%s/ct/v1/get-entries?start=%d&end=%d", ctURL, entry.Index, entry.Index)
	}

	// Handle gosec G115 warning
	if entry.Index < 0 {
		return models.Data{}, fmt.Errorf("invalid cert index: %d", entry.Index)
	}

	// Create main data structure
	data := models.Data{
		CertIndex: uint64(entry.Index),
		CertLink:  certLink,
		Seen:      float64(time.Now().UnixMilli()) / 1_000,
		Source: models.Source{
			Name:          logName,
			URL:           ctURL,
			Timestamp:     float64(entry.Leaf.TimestampedEntry.Timestamp) / 1_000,
			Operator:      operatorName,
			NormalizedURL: normalizeCtlogURL(ctURL),
			Type:          logType,
		},
		UpdateType: "X509LogEntry",
	}

	// Convert RawLogEntry to ct.LogEntry
	logEntry, conversionErr := entry.ToLogEntry()
	if conversionErr != nil {
		log.Println("Could not convert entry to LogEntry: ", conversionErr)
		return models.Data{}, fmt.Errorf("could not convert entry to logentry: %w", conversionErr)
	}

	var cert *x509.Certificate
	var rawData []byte
	var isPrecert bool

	switch {
	case logEntry.X509Cert != nil:
		cert = logEntry.X509Cert
		rawData = logEntry.X509Cert.Raw
		isPrecert = false
	case logEntry.Precert != nil:
		cert = logEntry.Precert.TBSCertificate
		rawData = logEntry.Precert.Submitted.Data
		isPrecert = true
	default:
		return models.Data{}, ErrNoCertFound
	}

	// Calculate certificate hash from the raw DER bytes of the certificate
	data.LeafCert = leafCertFromX509cert(*cert)

	// recalculate hashes if the certificate is a precertificate
	if isPrecert {
		calculatedHash := calculateSHA1(rawData)
		data.LeafCert.Fingerprint = calculatedHash
		data.LeafCert.SHA1 = calculatedHash
		data.LeafCert.SHA256 = calculateSHA256(rawData)

		// Since we use the TBSCertificate to parse the LeafCert, the PoisonByte indicator cannot be set by our parser.
		// According to RFC 6962 Section 3.2 the `"tbs_certificate" is the DER-encoded TBSCertificate (see [RFC5280])
		// component of the Precertificate -- that is, without the signature and the poison extension.`
		// Since the PoisonByte Extension `is to ensure that the Precertificate cannot be validated by a standard
		// X.509v3 client`, we can safely set it for each precertificate.
		data.LeafCert.Extensions.CTLPoisonByte = true
	}

	certAsDER := base64.StdEncoding.EncodeToString(entry.Cert.Data)
	data.LeafCert.AsDER = certAsDER

	chain, parseErr := parseCertificateChain(logEntry)
	if parseErr != nil {
		log.Println("Could not parse certificate chain: ", parseErr)
		return models.Data{}, parseErr
	}

	data.Chain = chain

	return data, nil
}

// parseCertificateChain returns the certificate chain in form of a []LeafCert from the given *ct.LogEntry.
func parseCertificateChain(logEntry *ct.LogEntry) ([]models.LeafCert, error) {
	chain := make([]models.LeafCert, len(logEntry.Chain))

	for i, chainEntry := range logEntry.Chain {
		myCert, parseErr := x509.ParseCertificate(chainEntry.Data)
		if parseErr != nil || myCert == nil {
			return nil, fmt.Errorf("could not parse certificate: %w", parseErr)
		}

		leafCert := leafCertFromX509cert(*myCert)
		chain[i] = leafCert
	}

	return chain, nil
}

// leafCertFromX509cert converts a x509.Certificate to the custom LeafCert data structure.
func leafCertFromX509cert(cert x509.Certificate) models.LeafCert {
	leafCert := models.LeafCert{
		AllDomains:         cert.DNSNames,
		Extensions:         models.Extensions{},
		NotAfter:           cert.NotAfter.Unix(),
		NotBefore:          cert.NotBefore.Unix(),
		SerialNumber:       formatSerialNumber(cert.SerialNumber),
		SignatureAlgorithm: parseSignatureAlgorithm(cert.SignatureAlgorithm),
		IsCA:               cert.IsCA,
	}

	// The zero value of DomainsEntry.Data is nil, but we want an empty array - especially for JSON marshaling later.
	if leafCert.AllDomains == nil {
		leafCert.AllDomains = []string{}
	}

	leafCert.Subject = buildSubject(cert.Subject)
	if *leafCert.Subject.CN != "" && !leafCert.IsCA {
		domainAlreadyAdded := slices.Contains(leafCert.AllDomains, *leafCert.Subject.CN)

		if !domainAlreadyAdded {
			leafCert.AllDomains = append(leafCert.AllDomains, *leafCert.Subject.CN)
		}
	}

	leafCert.Issuer = buildSubject(cert.Issuer)

	leafCert.AsDER = base64.StdEncoding.EncodeToString(cert.Raw)
	leafCert.Fingerprint = calculateSHA1(cert.Raw)
	leafCert.SHA1 = leafCert.Fingerprint
	leafCert.SHA256 = calculateSHA256(cert.Raw)

	// TODO fix Extensions - check x509util.go
	for _, extension := range cert.Extensions {
		switch {
		case extension.Id.Equal(x509.OIDExtensionAuthorityKeyId):
			leafCert.Extensions.AuthorityKeyIdentifier = formatKeyID(cert.AuthorityKeyId)
		case extension.Id.Equal(x509.OIDExtensionKeyUsage):
			keyUsage := keyUsageToString(cert.KeyUsage)
			leafCert.Extensions.KeyUsage = &keyUsage
		case extension.Id.Equal(x509.OIDExtensionSubjectKeyId):
			leafCert.Extensions.SubjectKeyIdentifier = formatKeyID(cert.SubjectKeyId)
		case extension.Id.Equal(x509.OIDExtensionBasicConstraints):
			isCA := strings.ToUpper(fmt.Sprintf("CA:%t", cert.IsCA))
			leafCert.Extensions.BasicConstraints = &isCA
		case extension.Id.Equal(x509.OIDExtensionSubjectAltName):
			var buf bytes.Buffer
			for _, name := range cert.DNSNames {
				commaAppend(&buf, "DNS:"+name)
			}

			for _, email := range cert.EmailAddresses {
				commaAppend(&buf, "email:"+email)
			}

			for _, ip := range cert.IPAddresses {
				commaAppend(&buf, "IP Address:"+ip.String())
			}

			subjectAltName := buf.String()
			leafCert.Extensions.SubjectAltName = &subjectAltName
		case extension.Id.Equal(x509.OIDExtensionAuthorityInfoAccess):
			var buf bytes.Buffer
			for _, issuer := range cert.IssuingCertificateURL {
				commaAppend(&buf, "URI:"+issuer)
			}

			for _, ocsp := range cert.OCSPServer {
				commaAppend(&buf, "URI:"+ocsp)
			}

			result := buf.String()
			leafCert.Extensions.AuthorityInfoAccess = &result
		case extension.Id.Equal(x509.OIDExtensionCTPoison):
			leafCert.Extensions.CTLPoisonByte = true
		case extension.Id.Equal(x509.OIDExtensionCertificatePolicies):
			var builder strings.Builder
			for _, policy := range cert.PolicyIdentifiers {
				// The current way of joining the string leaves us with a trailing newline,
				// but that's how the original certstream server does it too.
				builder.WriteString("Policy: ")
				builder.WriteString(policy.String())
				builder.WriteString("\n")
			}

			policyString := builder.String()
			leafCert.Extensions.CertificatePolicies = &policyString
		}
	}

	return leafCert
}

// buildSubject generates a Subject struct from the given pkix.Name.
func buildSubject(certSubject pkix.Name) models.Subject {
	subject := models.Subject{
		C:  parseName(certSubject.Country),
		CN: &certSubject.CommonName,
		L:  parseName(certSubject.Locality),
		O:  parseName(certSubject.Organization),
		OU: parseName(certSubject.OrganizationalUnit),
		ST: parseName(certSubject.StreetAddress),
	}

	var aggregated string

	if subject.C != nil {
		aggregated += "/C=" + *subject.C
	}

	if subject.CN != nil {
		aggregated += "/CN=" + *subject.CN
	}

	if subject.L != nil {
		aggregated += "/L=" + *subject.L
	}

	if subject.O != nil {
		aggregated += "/O=" + *subject.O
	}

	if subject.OU != nil {
		aggregated += "/OU=" + *subject.OU
	}

	if subject.ST != nil {
		aggregated += "/ST=" + *subject.ST
	}

	subject.Aggregated = &aggregated

	return subject
}

// formatKeyID transforms the AuthorityKeyIdentifier to be more readable.
func formatKeyID(keyID []byte) *string {
	tmp := hex.EncodeToString(keyID)
	var digest string

	for i := 0; i < len(tmp); i += 2 {
		digest = digest + ":" + tmp[i:i+2]
	}

	digest = strings.TrimLeft(digest, ":")
	digest = "keyid:" + digest

	return &digest
}

func formatSerialNumber(serialNumber *big.Int) string {
	sn := fmt.Sprintf("%X", serialNumber)
	if len(sn)%2 == 1 {
		sn = "0" + sn
	}

	return sn
}

func parseName(input []string) *string {
	if input == nil {
		return nil
	}

	var result string
	for _, s := range input {
		if len(result) > 0 {
			result += ","
		}

		result += s
	}

	return &result
}

// calculateHash takes a hash.Hash implementation and calculates the hash of the given data.
// It returns the hash in the format "XX:XX:XX:...".
func calculateHash(data []byte, certHasher hash.Hash) string {
	_, e := certHasher.Write(data)
	if e != nil {
		log.Printf("Error while hashing cert: %s\n", e)
		return ""
	}

	certHash := fmt.Sprintf("%02x", certHasher.Sum(nil))
	certHash = strings.ToUpper(certHash)

	var result bytes.Buffer

	//nolint:intrange
	for i := 0; i < len(certHash); i++ {
		if i%2 == 0 && i > 0 {
			result.WriteByte(':')
		}

		c := certHash[i]
		result.WriteByte(c)
	}

	return result.String()
}

// calculateSHA1 calculates the SHA1 fingerprint of the given data.
func calculateSHA1(data []byte) string {
	return calculateHash(data, sha1.New()) //nolint:gosec
}

// calculateSHA256 calculates the SHA256 fingerprint of the given data.
func calculateSHA256(data []byte) string {
	return calculateHash(data, sha256.New())
}

func parseSignatureAlgorithm(signatureAlgoritm x509.SignatureAlgorithm) string {
	switch signatureAlgoritm {
	case x509.MD2WithRSA:
		return "md2, rsa"
	case x509.MD5WithRSA:
		return "md5, rsa"
	case x509.SHA1WithRSA:
		return "sha1, rsa"
	case x509.SHA256WithRSA:
		return "sha256, rsa"
	case x509.SHA384WithRSA:
		return "sha384, rsa"
	case x509.SHA512WithRSA:
		return "sha512, rsa"
	case x509.SHA256WithRSAPSS:
		return "sha256, rsa-pss"
	case x509.SHA384WithRSAPSS:
		return "sha384, rsa-pss"
	case x509.SHA512WithRSAPSS:
		return "sha512, rsa-pss"
	case x509.DSAWithSHA1:
		return "dsa, sha1"
	case x509.DSAWithSHA256:
		return "dsa, sha256"
	case x509.ECDSAWithSHA1:
		return "ecdsa, sha1"
	case x509.ECDSAWithSHA256:
		return "ecdsa, sha256"
	case x509.ECDSAWithSHA384:
		return "ecdsa, sha384"
	case x509.ECDSAWithSHA512:
		return "ecdsa, sha512"
	case x509.PureEd25519:
		return "ed25519"
	case x509.UnknownSignatureAlgorithm:
		fallthrough
	default:
		return "unknown"
	}
}

// commaAppend lets you append a string with a comma prepended to a buffer.
func commaAppend(buf *bytes.Buffer, s string) {
	if buf.Len() > 0 {
		buf.WriteString(", ")
	}

	buf.WriteString(s)
}

func keyUsageToString(k x509.KeyUsage) string {
	var buf bytes.Buffer
	if k&x509.KeyUsageDigitalSignature != 0 {
		commaAppend(&buf, "Digital Signature")
	}

	if k&x509.KeyUsageContentCommitment != 0 {
		commaAppend(&buf, "Content Commitment")
	}

	if k&x509.KeyUsageKeyEncipherment != 0 {
		commaAppend(&buf, "Key Encipherment")
	}

	if k&x509.KeyUsageDataEncipherment != 0 {
		commaAppend(&buf, "Data Encipherment")
	}

	if k&x509.KeyUsageKeyAgreement != 0 {
		commaAppend(&buf, "Key Agreement")
	}

	if k&x509.KeyUsageCertSign != 0 {
		commaAppend(&buf, "Certificate Signing")
	}

	if k&x509.KeyUsageCRLSign != 0 {
		commaAppend(&buf, "CRL Signing")
	}

	if k&x509.KeyUsageEncipherOnly != 0 {
		commaAppend(&buf, "Encipher Only")
	}

	if k&x509.KeyUsageDecipherOnly != 0 {
		commaAppend(&buf, "Decipher Only")
	}

	return buf.String()
}

// ParseCertstreamEntry creates an Entry from a ct.RawLogEntry.
func ParseCertstreamEntry(rawEntry *ct.RawLogEntry, operatorName, logname, ctURL, logType string) (models.Entry, error) {
	if rawEntry == nil {
		return models.Entry{}, ErrEntryNil
	}

	data, err := parseData(rawEntry, operatorName, logname, ctURL, logType)
	if err != nil {
		return models.Entry{}, err
	}

	entry := models.Entry{
		Data:        data,
		MessageType: "certificate_update",
	}

	return entry, nil
}

package certificatetransparency

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"log"
	"math"
	"net/http"
	"slices"
	"strconv"
	"strings"
	"time"

	ct "github.com/google/certificate-transparency-go"
	"github.com/google/trillian/client/backoff"
	"golang.org/x/crypto/cryptobyte"
)

const TileSize = 256

// TiledCheckpoint represents the checkpoint information from a tiled CT log.
type TiledCheckpoint struct {
	Origin string
	Size   uint64
	Hash   string
}

// TileLeaf represents a single entry in a tile.
type TileLeaf struct {
	Timestamp     uint64
	EntryType     uint16
	X509Entry     []byte // For X.509 certificates
	PrecertEntry  []byte // For precertificates
	Chain         [][]byte
	IssuerKeyHash [32]byte
}

var (
	EntryTypeCert    uint16
	EntryTypePrecert uint16 = 1
)

// encodeTilePath encodes a tile index into the proper path format.
func encodeTilePath(index uint64) string {
	if index == 0 {
		return "000"
	}

	// Collect 3-digit groups
	var groups []uint64
	for n := index; n > 0; n /= 1000 {
		groups = append(groups, n%1000)
	}

	// Build path from groups in reverse
	var builder strings.Builder
	for i, v := range slices.Backward(groups) {
		if i < len(groups)-1 {
			builder.WriteByte('/')
		}

		if i > 0 {
			builder.WriteByte('x')
		}

		fmt.Fprintf(&builder, "%03d", v)
	}

	return builder.String()
}

// FetchCheckpoint fetches the checkpoint from a tiled CT log using the provided client.
func FetchCheckpoint(ctx context.Context, client *http.Client, baseURL string) (*TiledCheckpoint, error) {
	baseURL = strings.TrimRight(baseURL, "/")
	url := baseURL + "/checkpoint"

	req, newReqErr := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if newReqErr != nil {
		return nil, fmt.Errorf("failed to create checkpoint request: %w", newReqErr)
	}

	req.Header.Set("User-Agent", UserAgent)

	resp, reqErr := client.Do(req)
	if reqErr != nil {
		return nil, fmt.Errorf("failed to execute checkpoint request: %w", reqErr)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("%w: unexpected status code %d", ErrRequestFailed, resp.StatusCode)
	}

	lines := make([]string, 0, 3)

	scanner := bufio.NewScanner(resp.Body)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}

	if scanErr := scanner.Err(); scanErr != nil {
		return nil, fmt.Errorf("failed reading response body: %w", scanErr)
	}

	if len(lines) < 3 {
		return nil, fmt.Errorf("%w: invalid checkpoint format: expected at least 3 lines, got %d", ErrCheckpointInvalidFormat, len(lines))
	}

	size, parseErr := strconv.ParseUint(lines[1], 10, 64)
	if parseErr != nil {
		return nil, fmt.Errorf("failed parsing tree size: %w", parseErr)
	}

	return &TiledCheckpoint{
		Origin: lines[0],
		Size:   size,
		Hash:   lines[2],
	}, nil
}

// ParseTileData parses the binary tile data into TileLeaf entries using cryptobyte.
func ParseTileData(data []byte) ([]TileLeaf, error) {
	var leaves []TileLeaf
	parser := cryptobyte.String(data)

	for !parser.Empty() {
		var leaf TileLeaf

		if !parser.ReadUint64(&leaf.Timestamp) || !parser.ReadUint16(&leaf.EntryType) {
			return nil, fmt.Errorf("header: %w", ErrInvalidDataTile)
		}

		switch leaf.EntryType {
		case 0: // x509_entry
			var cert cryptobyte.String
			var extensions, fingerprints cryptobyte.String

			if !parser.ReadUint24LengthPrefixed(&cert) ||
				!parser.ReadUint16LengthPrefixed(&extensions) ||
				!parser.ReadUint16LengthPrefixed(&fingerprints) {
				return nil, fmt.Errorf("x509_entry: %w", ErrInvalidDataTile)
			}

			leaf.X509Entry = append([]byte(nil), cert...)

			for !fingerprints.Empty() {
				var fp [32]byte
				if !fingerprints.CopyBytes(fp[:]) {
					return nil, ErrInvalidFingerprint
				}

				leaf.Chain = append(leaf.Chain, fp[:])
			}

		case 1: // precert_entry
			var issuerKeyHash [32]byte
			var defangedCrt, extensions, entry, fingerprints cryptobyte.String

			if !parser.CopyBytes(issuerKeyHash[:]) ||
				!parser.ReadUint24LengthPrefixed(&defangedCrt) ||
				!parser.ReadUint16LengthPrefixed(&extensions) ||
				!parser.ReadUint24LengthPrefixed(&entry) ||
				!parser.ReadUint16LengthPrefixed(&fingerprints) {
				return nil, fmt.Errorf("precert_entry: %w", ErrInvalidDataTile)
			}

			leaf.PrecertEntry = append([]byte(nil), defangedCrt...)
			leaf.IssuerKeyHash = issuerKeyHash

			for !fingerprints.Empty() {
				var fp [32]byte
				if !fingerprints.CopyBytes(fp[:]) {
					return nil, ErrInvalidFingerprint
				}

				leaf.Chain = append(leaf.Chain, fp[:])
			}

		default:
			return nil, fmt.Errorf("%w: %d", ErrUnknownEntryType, leaf.EntryType)
		}

		leaves = append(leaves, leaf)
	}

	return leaves, nil
}

// ConvertTileLeafToRawLogEntry converts a TileLeaf to ct.RawLogEntry for compatibility.
func ConvertTileLeafToRawLogEntry(leaf TileLeaf, index uint64) *ct.RawLogEntry {
	if index > math.MaxInt64 {
		log.Printf("index (%d) exceeds math.MaxInt64, skipping\n", index)
		return nil
	}

	rawEntry := &ct.RawLogEntry{
		Index: int64(index),
		Leaf: ct.MerkleTreeLeaf{
			Version:  ct.V1,
			LeafType: ct.TimestampedEntryLeafType,
		},
	}

	switch leaf.EntryType {
	case 0: // x509_entry
		// Use the DER certificate from X509Entry
		certData := leaf.X509Entry
		rawEntry.Leaf.TimestampedEntry = &ct.TimestampedEntry{
			Timestamp: leaf.Timestamp,
			EntryType: ct.X509LogEntryType,
			X509Entry: &ct.ASN1Cert{Data: certData},
		}
		rawEntry.Cert = ct.ASN1Cert{Data: certData}

	case 1: // precert_entry
		// Build a minimal PreCert. TBSCertificate is the defanged TBS; IssuerKeyHash from tile.
		rawEntry.Leaf.TimestampedEntry = &ct.TimestampedEntry{
			Timestamp: leaf.Timestamp,
			EntryType: ct.PrecertLogEntryType,
			PrecertEntry: &ct.PreCert{
				IssuerKeyHash:  leaf.IssuerKeyHash,
				TBSCertificate: leaf.PrecertEntry,
			},
		}

	default:
		// Unknown type; leave as zero-value
	}

	return rawEntry
}

// DefaultMaxPartialWait is the default maximum time to wait before forcefully
// fetching a partial tile that has not yet grown into a full tile.
const DefaultMaxPartialWait = 1 * time.Minute

type StaticCTClient struct {
	url        string
	httpClient *http.Client
	backoff    backoff.Backoff
	userAgent  string
	ctIndex    uint64

	// Deferred partial-tile state.
	// partialTileIndex holds the tile index of the currently tracked partial tile.
	// partialTileFirstSeen is when that partial tile was first observed; zero means
	// no partial tile is being tracked.
	partialTileIndex     uint64
	partialTileFirstSeen time.Time
	maxPartialWait       time.Duration
}

func NewStaticCTClient(url string, httpClient *http.Client, userAgent string, startIndex uint64) *StaticCTClient {
	return &StaticCTClient{
		url:        strings.TrimRight(url, "/"),
		httpClient: httpClient,
		backoff: backoff.Backoff{
			Min:    2 * time.Second,
			Max:    15 * time.Second,
			Factor: 1.3,
			Jitter: true,
		},
		userAgent:      userAgent,
		ctIndex:        startIndex,
		maxPartialWait: DefaultMaxPartialWait,
	}
}

// Monitor continuously monitors the tiled CT log for new entries, starting from the current ctIndex.
func (s *StaticCTClient) Monitor(ctx context.Context, foundCert, foundPrecert func(*ct.RawLogEntry)) error {
	for {
		hadNewEntries, err := s.fetchAndProcessTiles(ctx, foundCert, foundPrecert)
		if err != nil {
			log.Printf("Error processing tiled log updates for '%s': %s\n", s.url, err)
			return err
		}

		// Reset backoff if we found new entries
		if hadNewEntries {
			s.backoff.Reset()
		}

		select {
		case <-ctx.Done():
			ctxErr := ctx.Err()
			if ctxErr != nil {
				return fmt.Errorf("context error: %w", ctxErr)
			}

			return nil
		case <-time.After(s.backoff.Duration()):
			// Continue to the next iteration
		}
	}
}

// fetchAndProcessTiles checks for new entries in the tiled log and processes them.
// It returns true if at least one full tile was fetched.
func (s *StaticCTClient) fetchAndProcessTiles(ctx context.Context, foundCert, foundPrecert func(*ct.RawLogEntry)) (bool, error) {
	// Fetch current checkpoint
	checkpoint, fetchErr := s.FetchCheckpoint(ctx)
	if fetchErr != nil {
		return false, fmt.Errorf("fetching checkpoint: %w", fetchErr)
	}

	currentTreeSize := checkpoint.Size
	if currentTreeSize <= s.ctIndex {
		// No new entries
		return false, nil
	}

	// Process entries from current index to new tree size
	startTile := s.ctIndex / TileSize
	endTile := currentTreeSize / TileSize

	// Process full tiles
	fetchedFullTiles := false
	for tileIndex := startTile; tileIndex < endTile; tileIndex++ {
		if err := s.processTile(ctx, tileIndex, 0, foundCert, foundPrecert); err != nil {
			return false, fmt.Errorf("processing tile %d: %w", tileIndex, err)
		}

		fetchedFullTiles = true
	}

	// When the current end tile has advanced past the tracked partial tile, that tile
	// has since become a full tile and been processed; reset tracking so we start
	// fresh for the new partial tile (if any).
	if endTile > s.partialTileIndex {
		s.partialTileFirstSeen = time.Time{}
	}

	// Process partial tiles.
	partialSize := currentTreeSize % TileSize
	if partialSize > 0 {
		switch {
		case s.partialTileFirstSeen.IsZero() || s.partialTileIndex != endTile:
			// First time we see this partial tile – start the deferral clock.
			s.partialTileIndex = endTile
			s.partialTileFirstSeen = time.Now()

			// log.Println("Deferring fetch of partial tile", endTile, "with size", partialSize)

		case time.Since(s.partialTileFirstSeen) >= s.maxPartialWait:
			// The partial tile has been pending too long – fetch it now to prevent
			// extreme processing delays on slow-growing logs.
			if err := s.processTile(ctx, endTile, partialSize, foundCert, foundPrecert); err != nil {
				log.Printf("Warning: error processing partial tile %d: %s\n", endTile, err)
			}

			// Reset tracking; the tile will be re-observed on the next poll if it
			// still hasn't grown into a full tile.
			s.partialTileFirstSeen = time.Time{}

		default:
			// Still within the deferral window – skip.
		}
	} else {
		// currentTreeSize is an exact multiple of TileSize; no partial tile exists.
		s.partialTileFirstSeen = time.Time{}
	}

	return fetchedFullTiles, nil
}

// processTile processes a single tile from the tiled log.
// partialWidth of 0 means full tile, otherwise fetch partial tile with that width.
func (s *StaticCTClient) processTile(ctx context.Context, tileIndex, partialWidth uint64, foundCert, foundPrecert func(*ct.RawLogEntry)) error {
	leaves, err := s.fetchTile(ctx, tileIndex, partialWidth)
	if err != nil {
		return fmt.Errorf("fetching tile: %w", err)
	}

	// Calculate the starting index for entries in this tile
	baseIndex := tileIndex * TileSize

	for i, leaf := range leaves {
		entryIndex := baseIndex + uint64(i)

		// Skip entries we've already processed
		if entryIndex < s.ctIndex {
			continue
		}

		// Convert TileLeaf to RawLogEntry for compatibility with existing parsing
		rawEntry := ConvertTileLeafToRawLogEntry(leaf, entryIndex)

		// Process the entry using existing callbacks
		switch leaf.EntryType {
		case EntryTypeCert:
			foundCert(rawEntry)
		case EntryTypePrecert:
			foundPrecert(rawEntry)
		default:
			log.Printf("Unknown entry type %d in tile %d, skipping entry at index %d\n", leaf.EntryType, tileIndex, entryIndex)
		}

		// Update the index
		s.ctIndex = entryIndex + 1
	}

	return nil
}

// fetchTile fetches a tile from the tiled CT log using the provided client.
// If partialWidth > 0, fetches a partial tile with that width (1-255).
func (s *StaticCTClient) fetchTile(ctx context.Context, tileIndex, partialWidth uint64) ([]TileLeaf, error) {
	tilePath := encodeTilePath(tileIndex)

	if partialWidth > 0 {
		tilePath = fmt.Sprintf("%s.p/%d", tilePath, partialWidth)
	}

	url := fmt.Sprintf("%s/tile/data/%s", s.url, tilePath)

	req, newReqErr := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if newReqErr != nil {
		return nil, fmt.Errorf("failed to create tile request: %w", newReqErr)
	}

	req.Header.Set("User-Agent", UserAgent)

	resp, reqErr := s.httpClient.Do(req)
	if reqErr != nil {
		return nil, fmt.Errorf("fetching tile %d: %w", tileIndex, reqErr)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("%w: unexpected status code %d", ErrRequestFailed, resp.StatusCode)
	}

	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("reading tile data: %w", err)
	}

	return ParseTileData(data)
}

// FetchCheckpoint fetches the checkpoint from a tiled CT log using the provided client.
func (s *StaticCTClient) FetchCheckpoint(ctx context.Context) (*TiledCheckpoint, error) {
	url := s.url + "/checkpoint"

	req, newReqErr := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if newReqErr != nil {
		return nil, fmt.Errorf("failed to create checkpoint request: %w", newReqErr)
	}

	req.Header.Set("User-Agent", UserAgent)

	resp, reqErr := s.httpClient.Do(req)
	if reqErr != nil {
		return nil, fmt.Errorf("failed to execute checkpoint request: %w", reqErr)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("%w: unexpected status code %d", ErrRequestFailed, resp.StatusCode)
	}

	lines := make([]string, 0, 3)

	scanner := bufio.NewScanner(resp.Body)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}

	if scanErr := scanner.Err(); scanErr != nil {
		return nil, fmt.Errorf("failed reading response body: %w", scanErr)
	}

	if len(lines) < 3 {
		return nil, fmt.Errorf("%w: invalid checkpoint format: expected at least 3 lines, got %d", ErrCheckpointInvalidFormat, len(lines))
	}

	size, parseErr := strconv.ParseUint(lines[1], 10, 64)
	if parseErr != nil {
		return nil, fmt.Errorf("failed parsing tree size: %w", parseErr)
	}

	return &TiledCheckpoint{
		Origin: lines[0],
		Size:   size,
		Hash:   lines[2],
	}, nil
}

package certificatetransparency

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync"
	"testing"

	ct "github.com/google/certificate-transparency-go"
	"golang.org/x/crypto/cryptobyte"
)

func Test_encodeTilePath(t *testing.T) {
	tests := []struct {
		name  string
		index uint64
		want  string
	}{
		{
			name:  "zero index",
			index: 0,
			want:  "000",
		},
		{
			name:  "single group padded",
			index: 1,
			want:  "001",
		},
		{
			name:  "single group max",
			index: 999,
			want:  "999",
		},
		{
			name:  "example from spec",
			index: 1_234_067,
			want:  "x001/x234/067",
		},
		{
			name:  "two groups exact thousand",
			index: 1_000,
			want:  "x001/000",
		},
		{
			name:  "two groups with remainder",
			index: 1_001,
			want:  "x001/001",
		},
		{
			name:  "two groups arbitrary",
			index: 123_456,
			want:  "x123/456",
		},
		{
			name:  "three groups",
			index: 1_000_000,
			want:  "x001/x000/000",
		},
		{
			name:  "four groups",
			index: 12_123_456_789,
			want:  "x012/x123/x456/789",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := encodeTilePath(tt.index)
			if got != tt.want {
				t.Errorf("encodeTilePath() = %v, want %v", got, tt.want)
			}
		})
	}
}

// fakeTiledLog serves a minimal static CT log (checkpoint and data tiles) and
// counts the requests it receives per path.
type fakeTiledLog struct {
	t        *testing.T
	mu       sync.Mutex
	size     uint64
	requests map[string]int
}

func newFakeTiledLog(t *testing.T, size uint64) (*fakeTiledLog, *httptest.Server) {
	t.Helper()

	l := &fakeTiledLog{t: t, size: size, requests: make(map[string]int)}
	srv := httptest.NewServer(l)
	t.Cleanup(srv.Close)

	return l, srv
}

func (l *fakeTiledLog) grow(n uint64) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.size += n
}

func (l *fakeTiledLog) tileRequests() int {
	l.mu.Lock()
	defer l.mu.Unlock()

	n := 0

	for path, count := range l.requests {
		if strings.HasPrefix(path, "/tile/") {
			n += count
		}
	}

	return n
}

func (l *fakeTiledLog) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	l.mu.Lock()
	defer l.mu.Unlock()

	l.requests[r.URL.Path]++

	if r.URL.Path == "/checkpoint" {
		fmt.Fprintf(w, "example.com/log\n%d\nAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=\n", l.size)
		return
	}

	tilePath, ok := strings.CutPrefix(r.URL.Path, "/tile/data/")
	if !ok {
		http.NotFound(w, r)
		return
	}

	width := uint64(TileSize)

	if base, p, found := strings.Cut(tilePath, ".p/"); found {
		tilePath = base

		var err error

		width, err = strconv.ParseUint(p, 10, 64)
		if err != nil {
			http.NotFound(w, r)
			return
		}
	}

	var tileIndex uint64

	for tileIndex = 0; encodeTilePath(tileIndex) != tilePath; tileIndex++ {
		if tileIndex > l.size/TileSize {
			http.NotFound(w, r)
			return
		}
	}

	first := tileIndex * TileSize
	if first+width > l.size || (width < TileSize && first+width != l.size) {
		http.NotFound(w, r)
		return
	}

	var b cryptobyte.Builder

	for i := first; i < first+width; i++ {
		b.AddUint64(i)             // timestamp, set to the index for easy checking
		b.AddUint16(EntryTypeCert) // entry type
		b.AddUint24LengthPrefixed(func(b *cryptobyte.Builder) { b.AddBytes([]byte{0x30, 0x00}) })
		b.AddUint16LengthPrefixed(func(*cryptobyte.Builder) {})
		b.AddUint16LengthPrefixed(func(*cryptobyte.Builder) {})
	}

	data, err := b.Bytes()
	if err != nil {
		l.t.Errorf("building tile: %v", err)
		http.Error(w, err.Error(), http.StatusInternalServerError)

		return
	}

	_, _ = w.Write(data)
}

// runPoll performs a single fetchAndProcessTiles call and returns the indexes
// of the entries it emitted.
func runPoll(t *testing.T, c *StaticCTClient) (indexes []uint64, hadNewEntries bool) {
	t.Helper()

	found := func(e *ct.RawLogEntry) {
		if uint64(e.Index) != e.Leaf.TimestampedEntry.Timestamp {
			t.Errorf("entry index %d does not match tile content %d", e.Index, e.Leaf.TimestampedEntry.Timestamp)
		}

		indexes = append(indexes, uint64(e.Index))
	}

	hadNewEntries, err := c.fetchAndProcessTiles(context.Background(), found, found)
	if err != nil {
		t.Fatalf("fetchAndProcessTiles: %v", err)
	}

	return indexes, hadNewEntries
}

func expectRange(t *testing.T, got []uint64, start, end uint64) {
	t.Helper()

	if uint64(len(got)) != end-start {
		t.Fatalf("got %d entries, want %d (indexes %v)", len(got), end-start, got)
	}

	for i, idx := range got {
		if idx != start+uint64(i) {
			t.Fatalf("entry %d has index %d, want %d", i, idx, start+uint64(i))
		}
	}
}

func TestStaticCTClient_NoRefetchWhenIdle(t *testing.T) {
	log, srv := newFakeTiledLog(t, 300)
	c := NewStaticCTClient(srv.URL, srv.Client(), "test", 0)
	// A partial tile is always deferred the first time it is observed, and
	// fetched on the next poll once the deferral window has expired.
	c.maxPartialWait = 0

	indexes, hadNewEntries := runPoll(t, c)
	expectRange(t, indexes, 0, 256)

	if !hadNewEntries {
		t.Error("first poll should report new entries")
	}

	indexes, _ = runPoll(t, c)
	expectRange(t, indexes, 256, 300)

	if c.ctIndex != 300 {
		t.Errorf("ctIndex = %d, want 300", c.ctIndex)
	}

	tileRequests := log.tileRequests()

	// The log has not grown: no tile should be fetched again, and no entry
	// should be emitted again.
	for range 3 {
		indexes, hadNewEntries = runPoll(t, c)
		expectRange(t, indexes, 0, 0)

		if hadNewEntries {
			t.Error("poll on an idle log should not report new entries")
		}
	}

	if got := log.tileRequests(); got != tileRequests {
		t.Errorf("idle polls fetched %d tiles, want 0", got-tileRequests)
	}
}

func TestStaticCTClient_StartAtCheckpointSize(t *testing.T) {
	log, srv := newFakeTiledLog(t, 300)
	c := NewStaticCTClient(srv.URL, srv.Client(), "test", 0)
	c.maxPartialWait = 0
	// Like runTiledWorker without recovery, start at the current tree size.
	c.ctIndex = 300

	indexes, _ := runPoll(t, c)
	expectRange(t, indexes, 0, 0)

	// The first new entry after startup must not be skipped. The partial tile
	// is deferred once, then fetched on the next poll.
	log.grow(1)
	runPoll(t, c)
	indexes, _ = runPoll(t, c)
	expectRange(t, indexes, 300, 301)

	log.grow(2)
	runPoll(t, c)
	indexes, _ = runPoll(t, c)
	expectRange(t, indexes, 301, 303)
}

func TestStaticCTClient_DeferPartialTiles(t *testing.T) {
	log, srv := newFakeTiledLog(t, 256)
	c := NewStaticCTClient(srv.URL, srv.Client(), "test", 256)

	// A new partial tile is observed but not fetched within the deferral window.
	log.grow(10)
	indexes, hadNewEntries := runPoll(t, c)
	expectRange(t, indexes, 0, 0)

	if hadNewEntries {
		t.Error("deferred partial should not report new entries")
	}

	if got := log.tileRequests(); got != 0 {
		t.Errorf("fetched %d tiles during deferral, want 0", got)
	}

	// Once the tile fills up, the full tile is fetched and every entry is
	// emitted exactly once.
	log.grow(246)
	indexes, hadNewEntries = runPoll(t, c)
	expectRange(t, indexes, 256, 512)

	if !hadNewEntries {
		t.Error("full tile fetch should report new entries")
	}

	if got := log.tileRequests(); got != 1 {
		t.Errorf("fetched %d tiles, want 1", got)
	}

	// When the deferral window expires, the partial is fetched once, and then
	// not again until the log grows.
	log.grow(5)
	runPoll(t, c) // starts the deferral clock
	c.partialTileFirstSeen = c.partialTileFirstSeen.Add(-2 * DefaultMaxPartialWait)
	indexes, _ = runPoll(t, c)
	expectRange(t, indexes, 512, 517)

	tileRequests := log.tileRequests()

	for range 3 {
		indexes, _ = runPoll(t, c)
		expectRange(t, indexes, 0, 0)
	}

	if got := log.tileRequests(); got != tileRequests {
		t.Errorf("idle polls fetched %d tiles, want 0", got-tileRequests)
	}
}

package certificatetransparency

import (
	"context"
	"errors"
	"fmt"
	"log"
	"math"
	"net/http"
	"path/filepath"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/d-Rickyy-b/certstream-server-go/internal/broadcast"
	"github.com/d-Rickyy-b/certstream-server-go/internal/config"
	"github.com/d-Rickyy-b/certstream-server-go/internal/metrics"
	"github.com/d-Rickyy-b/certstream-server-go/internal/models"
	"github.com/d-Rickyy-b/certstream-server-go/internal/web"

	ct "github.com/google/certificate-transparency-go"
	"github.com/google/certificate-transparency-go/client"
	"github.com/google/certificate-transparency-go/jsonclient"
	"github.com/google/certificate-transparency-go/loglist3"
	"github.com/google/certificate-transparency-go/scanner"
)

var UserAgent = fmt.Sprintf("Certstream Server v%s (github.com/d-Rickyy-b/certstream-server-go)", config.Version)

// Watcher is a central component within certstream-server-go. It manages the workers for all the monitored ct logs.
// It keeps track of all the monitored logs and periodically checks for new logs that aren't monitored yet.
type Watcher struct {
	workers    []*worker
	workersMu  sync.RWMutex
	wg         sync.WaitGroup
	context    context.Context
	certChan   chan models.Entry
	cancelFunc context.CancelFunc
}

// NewWatcher creates a new Watcher.
func NewWatcher() *Watcher {
	certChan := make(chan models.Entry, 5000)

	return &Watcher{
		certChan: certChan,
	}
}

// NewWatcherWithChannel creates a new Watcher and initializes it with the provided cert channel.
func NewWatcherWithChannel(certChan chan models.Entry) *Watcher {
	return &Watcher{
		certChan: certChan,
	}
}

// Start starts the watcher. This method is blocking.
func (w *Watcher) Start() {
	w.context, w.cancelFunc = context.WithCancel(context.Background())

	// Create new certChan if it doesn't exist yet
	if w.certChan == nil {
		w.certChan = make(chan models.Entry, 5000)
	}

	if config.AppConfig.General.Recovery.Enabled {
		ctIndexFilePath, err := filepath.Abs(config.AppConfig.General.Recovery.CTIndexFile)
		if err != nil {
			log.Printf("Error getting absolute path for CT index file: '%s', %s\n", config.AppConfig.General.Recovery.CTIndexFile, err)
			return
		}

		// Load saved CT indexes from provided index file
		metrics.Metrics.LoadCTIndex(ctIndexFilePath)

		// Start background job to save CTIndexes at regular intervals
		storageInterval := time.Second * 30
		go metrics.Metrics.SaveCertIndexesAtInterval(w.context, storageInterval, ctIndexFilePath)
	}

	// initialize the watcher with currently available logs
	w.updateLogs()

	log.Println("Started CT watcher")

	go certHandler(w.certChan)
	go w.watchNewLogs()

	// Wait for all workers to finish
	w.wg.Wait()
	close(w.certChan)
}

// watchNewLogs is a blocking method that continuously monitors the Google log list for new logs and starts
// a worker for each new log found. It can be stopped by cancelling the watcher's context (e.g. via Stop()).
func (w *Watcher) watchNewLogs() {
	// Check for new logs once every hour
	ticker := time.NewTicker(1 * time.Hour)

	for {
		select {
		case <-ticker.C:
			w.updateLogs()
		case <-w.context.Done():
			ticker.Stop()
			return
		}
	}
}

// updateLogs checks the Google log list for new logs once and adds new workers for those to the watcher.
func (w *Watcher) updateLogs() {
	// Get a list of urls of all CT logs provided by Google
	logList, err := getAllLogs(googleLogListFetcher)
	if err != nil {
		log.Println(err)
		return
	}

	log.Println("Checking for new ct logs...")

	// Track all URLs that should be monitored after reconciliation.
	monitoredURLs := make(map[string]struct{})
	newCTs := 0

	w.workersMu.Lock()
	defer w.workersMu.Unlock()

	for _, operator := range logList.Operators {
		// Classic logs
		for _, transparencyLog := range operator.Logs {
			url := transparencyLog.URL
			desc := transparencyLog.Description
			normURL := normalizeCtlogURL(url)

			if transparencyLog.State.LogStatus() == loglist3.RetiredLogStatus {
				log.Printf("Skipping retired CT log: %s\n", normURL)
				continue
			}

			monitoredURLs[normURL] = struct{}{}

			if w.addLogIfNew(operator.Name, desc, url, false) {
				newCTs++
			}
		}

		// Tiled logs
		for _, transparencyLog := range operator.TiledLogs {
			url := transparencyLog.MonitoringURL
			desc := transparencyLog.Description
			normURL := normalizeCtlogURL(url)

			if transparencyLog.State.LogStatus() == loglist3.RetiredLogStatus {
				log.Printf("Skipping retired CT log: %s\n", normURL)
				continue
			}

			monitoredURLs[normURL] = struct{}{}

			if w.addLogIfNew(operator.Name, desc, url, true) {
				newCTs++
			}
		}
	}

	log.Printf("New ct logs found: %d\n", newCTs)

	// Optionally stop workers for logs not in the monitoredURLs set
	if *config.AppConfig.General.DropOldLogs {
		removed := 0

		for _, ctWorker := range w.workers {
			normURL := normalizeCtlogURL(ctWorker.ctURL)
			if _, ok := monitoredURLs[normURL]; !ok {
				log.Printf("Stopping worker. CT URL not found in LogList or retired: '%s'\n", ctWorker.ctURL)
				ctWorker.stop()

				removed++
			}
		}

		log.Printf("Removed ct logs: %d\n", removed)
	}

	log.Printf("Currently monitored ct logs: %d\n", len(w.workers))
}

// addLogIfNew checks if a log is already being watched and adds it if not.
// Returns true if a new log was added, false otherwise.
func (w *Watcher) addLogIfNew(operatorName, description, url string, isTiled bool) bool {
	normURL := normalizeCtlogURL(url)

	// Check if the log is already being watched
	for _, ctWorker := range w.workers {
		workerURL := normalizeCtlogURL(ctWorker.ctURL)
		if workerURL == normURL {
			return false
		}
	}

	// Log is not being watched yet, so add it
	w.wg.Add(1)

	lastCTIndex := metrics.Metrics.GetCTIndex(normURL)
	ctWorker := worker{
		name:         description,
		operatorName: operatorName,
		ctURL:        url,
		entryChan:    w.certChan,
		ctIndex:      lastCTIndex,
		isTiled:      isTiled,
	}
	w.workers = append(w.workers, &ctWorker)

	metrics.Metrics.Init(operatorName, normURL)

	// Start a goroutine for each worker
	go func() {
		defer w.wg.Done()

		ctWorker.startDownloadingCerts(w.context)
		w.discardWorker(&ctWorker)
	}()

	return true
}

// discardWorker removes a worker from the watcher's list of workers.
// This needs to be done when a worker stops.
func (w *Watcher) discardWorker(worker *worker) {
	log.Println("Removing worker for CT log:", worker.ctURL)

	w.workersMu.Lock()
	defer w.workersMu.Unlock()

	for i, wo := range w.workers {
		if wo == worker {
			w.workers = append(w.workers[:i], w.workers[i+1:]...)
			return
		}
	}
}

// Stop stops the watcher.
func (w *Watcher) Stop() {
	log.Printf("Stopping watcher\n")

	if config.AppConfig.General.Recovery.Enabled {
		// Store current CT Indexes before shutting down
		filePath := config.AppConfig.General.Recovery.CTIndexFile

		err := metrics.Metrics.SaveCertIndexes(filePath)
		if err != nil {
			log.Printf("Failed to save CT index file: %v\n", err)
		}
	}

	w.cancelFunc()
}

// CreateIndexFile creates a ct_index.json file based on the current STHs of all available logs.
func (w *Watcher) CreateIndexFile(filePath string) error {
	logs, err := getAllLogs(googleLogListFetcher)
	if err != nil {
		return err
	}

	httpClient := newHTTPClient()
	w.context, w.cancelFunc = context.WithCancel(context.Background())

	log.Println("Fetching current STH for all logs...")

	for _, operator := range logs.Operators {
		// Iterate over each log of the operator
		for _, transparencyLog := range operator.Logs {
			if transparencyLog.State.LogStatus() == loglist3.RetiredLogStatus {
				log.Printf("Skipping retired CT log: %s\n", transparencyLog.URL)
				continue
			}

			normalizedURL := normalizeCtlogURL(transparencyLog.URL)
			metrics.Metrics.Init(operator.Name, normalizedURL)
			log.Println("Fetching STH for", normalizedURL)

			jsonClient, e := client.New(transparencyLog.URL, httpClient, jsonclient.Options{UserAgent: UserAgent})
			if e != nil {
				log.Printf("Error creating JSON client: %s\n", e)
				continue
			}

			sth, getSTHerr := jsonClient.GetSTH(w.context)
			if getSTHerr != nil {
				// TODO this can happen due to a 429 error. We should retry the request
				log.Printf("Could not get STH for '%s': %s\n", transparencyLog.URL, getSTHerr)
				continue
			}

			metrics.Metrics.SetCTIndex(normalizedURL, sth.TreeSize)
		}

		for _, transparencyLog := range operator.TiledLogs {
			if transparencyLog.State.LogStatus() == loglist3.RetiredLogStatus {
				log.Printf("Skipping retired CT log: %s\n", transparencyLog.MonitoringURL)
				continue
			}

			normalizedURL := normalizeCtlogURL(transparencyLog.MonitoringURL)
			metrics.Metrics.Init(operator.Name, normalizedURL)
			log.Println("Fetching checkpoint for", normalizedURL)

			staticCTClient := NewStaticCTClient(transparencyLog.MonitoringURL, httpClient, UserAgent, 0)

			checkpoint, fetchErr := staticCTClient.FetchCheckpoint(w.context)
			if fetchErr != nil {
				log.Printf("Could not get checkpoint for '%s': %s\n", transparencyLog.MonitoringURL, fetchErr)
				return ErrFetchingSTHFailed
			}

			metrics.Metrics.SetCTIndex(normalizedURL, checkpoint.Size)
		}
	}

	w.cancelFunc()

	saveErr := metrics.Metrics.SaveCertIndexes(filePath)
	if saveErr != nil {
		return fmt.Errorf("failed to save cert index: %w", saveErr)
	}

	log.Println("Index file saved to", filePath)

	return nil
}

// A worker processes a single CT log.
type worker struct {
	name         string
	operatorName string
	ctURL        string
	entryChan    chan models.Entry
	ctIndex      uint64
	mu           sync.Mutex
	running      bool
	cancel       context.CancelFunc
	isTiled      bool
}

// startDownloadingCerts starts downloading certificates from the CT log. This method is blocking.
func (w *worker) startDownloadingCerts(ctx context.Context) {
	ctx, w.cancel = context.WithCancel(ctx)

	// Normalize CT URL. We remove trailing slashes and prepend "https://" if it's not already there.
	w.ctURL = strings.TrimRight(w.ctURL, "/")
	if !strings.HasPrefix(w.ctURL, "https://") && !strings.HasPrefix(w.ctURL, "http://") {
		w.ctURL = "https://" + w.ctURL
	}

	log.Printf("Initializing worker for CT log: %s\n", w.ctURL)
	defer log.Printf("Stopping worker for CT log: %s\n", w.ctURL)

	w.mu.Lock()
	if w.running {
		log.Printf("Worker for '%s' already running\n", w.ctURL)
		w.mu.Unlock()

		return
	}

	w.running = true
	defer func() { w.running = false }()
	w.mu.Unlock()

	for {
		// reload the CT index from metrics before restarting the worker
		lastCTIndex := metrics.Metrics.GetCTIndex(normalizeCtlogURL(w.ctURL))
		w.ctIndex = lastCTIndex

		log.Printf("Starting worker for CT log: %s\n", w.ctURL)

		var workerErr error
		if w.isTiled {
			workerErr = w.runTiledWorker(ctx)
		} else {
			workerErr = w.runStandardWorker(ctx)
		}

		if workerErr != nil {
			switch {
			case errors.Is(workerErr, ErrFetchingSTHFailed):
				log.Printf("Worker for '%s' failed - could not fetch STH\n", w.ctURL)
				return
			case errors.Is(workerErr, ErrCreatingClient):
				log.Printf("Worker for '%s' failed - could not create client\n", w.ctURL)
				return
			case strings.Contains(workerErr.Error(), "no such host"):
				log.Printf("Worker for '%s' failed to resolve host: %s\n", w.ctURL, workerErr)
				return
			case errors.Is(workerErr, context.Canceled):
				log.Printf("Worker for '%s' canceled\n", w.ctURL)
				return
			}

			log.Printf("Worker for '%s' failed with unexpected error: %s\n", w.ctURL, workerErr)
		}

		// Check if the context was canceled
		select {
		case <-ctx.Done():
			log.Printf("Context was cancelled; Stopping worker for '%s'\n", w.ctURL)

			return
		default:
			log.Printf("Worker for '%s' sleeping for 5 seconds due to error\n", w.ctURL)
			time.Sleep(5 * time.Second)
			log.Printf("Restarting worker for '%s'\n", w.ctURL)

			continue
		}
	}
}

func (w *worker) stop() {
	w.mu.Lock()
	defer w.mu.Unlock()

	w.cancel()
}

// runStandardWorker runs the worker for a single standard CT log. This method is blocking.
func (w *worker) runStandardWorker(ctx context.Context) error {
	jsonClient, e := client.New(w.ctURL, newHTTPClient(), jsonclient.Options{UserAgent: UserAgent})
	if e != nil {
		log.Printf("Error creating JSON client: %s\n", e)
		return ErrCreatingClient
	}

	// If recovery is enabled, we start at the saved index. Otherwise, we start at the latest STH.
	recoveryEnabled := config.AppConfig.General.Recovery.Enabled
	if !recoveryEnabled {
		sth, getSTHerr := jsonClient.GetSTH(ctx)
		if getSTHerr != nil {
			// TODO this can happen due to a 429 error. We should retry the request
			log.Printf("Could not get STH for '%s': %s\n", w.ctURL, getSTHerr)
			return ErrFetchingSTHFailed
		}
		// Start at the latest STH to skip all the past certificates
		w.ctIndex = sth.TreeSize
	}

	// Handle gosec G115 warning
	if w.ctIndex > math.MaxInt64 {
		log.Printf("index (%d) exceeds math.MaxInt64, skipping\n", w.ctIndex)
		return nil
	}

	certScanner := scanner.NewScanner(jsonClient, scanner.ScannerOptions{
		FetcherOptions: scanner.FetcherOptions{
			BatchSize:     256,
			ParallelFetch: 1,
			StartIndex:    int64(w.ctIndex),
			Continuous:    true,
		},
		Matcher:     scanner.MatchAll{},
		PrecertOnly: false,
		NumWorkers:  1,
		BufferSize:  config.AppConfig.General.BufferSizes.CTLog,
	})

	scanErr := certScanner.Scan(ctx, w.foundCertCallback, w.foundPrecertCallback)
	if scanErr != nil {
		return fmt.Errorf("error scanning for certificates: %w", scanErr)
	}

	log.Printf("Exiting worker %s without error!\n", w.ctURL)

	return nil
}

// runTiledWorker runs the worker for a single tiled CT log. This method is blocking.
func (w *worker) runTiledWorker(ctx context.Context) error {
	httpClient := newHTTPClient()

	staticCTClient := NewStaticCTClient(w.ctURL, httpClient, UserAgent, w.ctIndex)

	// If recovery is enabled and the CT index is set, we start at the saved index. Otherwise, we start at the latest checkpoint.
	recoveryEnabled := config.AppConfig.General.Recovery.Enabled
	if !recoveryEnabled {
		checkpoint, err := staticCTClient.FetchCheckpoint(ctx)
		if err != nil {
			log.Printf("Could not get checkpoint for '%s': %s\n", w.ctURL, err)
			return ErrFetchingSTHFailed
		}
		// Start at the latest checkpoint to skip all the past certificates
		staticCTClient.ctIndex = checkpoint.Size
	}

	err := staticCTClient.Monitor(ctx, w.foundCertCallback, w.foundPrecertCallback)
	if err != nil {
		return fmt.Errorf("error scanning for certificates: %w", err)
	}

	return nil
}

// foundCertCallback is the callback that handles cases where new regular certs are found.
func (w *worker) foundCertCallback(rawEntry *ct.RawLogEntry) {
	logType := models.SourceIsRFC6962
	if w.isTiled {
		logType = models.SourceIsTiled
	}

	entry, parseErr := ParseCertstreamEntry(rawEntry, w.operatorName, w.name, w.ctURL, logType)
	if parseErr != nil {
		log.Println("Error parsing certstream entry: ", parseErr)
		return
	}

	entry.Data.UpdateType = "X509LogEntry"
	w.entryChan <- entry

	atomic.AddInt64(&metrics.ProcessedCerts, 1)
}

// foundPrecertCallback is the callback that handles cases where new precerts are found.
func (w *worker) foundPrecertCallback(rawEntry *ct.RawLogEntry) {
	logType := models.SourceIsRFC6962
	if w.isTiled {
		logType = models.SourceIsTiled
	}

	entry, parseErr := ParseCertstreamEntry(rawEntry, w.operatorName, w.name, w.ctURL, logType)
	if parseErr != nil {
		log.Println("Error parsing certstream entry: ", parseErr)
		return
	}

	entry.Data.UpdateType = "PrecertLogEntry"
	w.entryChan <- entry

	atomic.AddInt64(&metrics.ProcessedPrecerts, 1)
}

// certHandler takes the entries out of the entryChan channel and broadcasts them to all clients.
// Only a single instance of the certHandler runs per certstream server.
func certHandler(entryChan chan models.Entry) {
	var processed uint64

	for {
		entry := <-entryChan
		processed++

		if processed%1000 == 0 {
			log.Printf("Processed %d entries | Queue length: %d\n", processed, len(entryChan))
			// Every thousandth entry, we store one certificate as example
			web.SetExampleCert(entry)
		}

		// Run JSON encoding in the background and send the result to the clients.
		broadcast.ClientHandler.MessageQueue <- entry

		// Update metrics
		url := entry.Data.Source.NormalizedURL
		operator := entry.Data.Source.Operator
		index := entry.Data.CertIndex

		metrics.Metrics.Inc(operator, url, index)
	}
}

// newHTTPClient creates a new http.Client with reasonable timeouts and connection settings for interacting with CT logs.
func newHTTPClient() *http.Client {
	httpClient := http.Client{
		Timeout: 30 * time.Second,
		Transport: &http.Transport{
			TLSHandshakeTimeout:   30 * time.Second,
			ResponseHeaderTimeout: 30 * time.Second,
			MaxIdleConnsPerHost:   10,
			DisableKeepAlives:     false,
			MaxIdleConns:          100,
			IdleConnTimeout:       90 * time.Second,
			ExpectContinueTimeout: 1 * time.Second,
		},
	}

	return &httpClient
}

package certstream

// The certstream package provides the main entry point for the certstream-server-go application.
// It initializes the webserver and the watcher for the certificate transparency logs.
// It also handles signals for graceful shutdown of the server.

import (
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"strconv"
	"syscall"

	"github.com/d-Rickyy-b/certstream-server-go/internal/broadcast"
	"github.com/d-Rickyy-b/certstream-server-go/internal/certificatetransparency"
	"github.com/d-Rickyy-b/certstream-server-go/internal/config"
	"github.com/d-Rickyy-b/certstream-server-go/internal/metrics"
	"github.com/d-Rickyy-b/certstream-server-go/internal/web"
)

type Certstream struct {
	webserver     *web.Server
	metricsServer *web.Server
	watcher       *certificatetransparency.Watcher
	config        config.Config
}

func NewRawCertstream(config config.Config) *Certstream {
	cs := Certstream{}
	cs.config = config

	return &cs
}

// NewCertstreamServer creates a new Certstream server from a config struct.
func NewCertstreamServer(cfg config.Config) (*Certstream, error) {
	cs := NewRawCertstream(cfg)

	// Start the broadcast dispatcher
	broadcast.NewDispatcher()
	broadcast.ClientHandler.Start()

	// TODO: add support do disable websocket Server
	// Initialize the webserver used for the websocket server
	webserver := web.NewWebsocketServer(
		cfg.Webserver.ListenAddr,
		cfg.Webserver.ListenPort,
		cfg.Webserver.CertPath,
		cfg.Webserver.CertKeyPath,
	)
	cs.webserver = webserver
	cs.watcher = certificatetransparency.NewWatcher()

	// Setup metrics server
	cs.setupMetrics(webserver)

	// Initialize the stream processors if configured and enabled.
	for _, streamProcessor := range cfg.StreamProcessing {
		if !*streamProcessor.Enabled {
			continue
		}

		addr := net.JoinHostPort(streamProcessor.ServerAddr, strconv.Itoa(streamProcessor.ServerPort))
		log.Printf("Initializing stream processor: %s at %s\n", streamProcessor.Name, addr)

		var subscriptionType broadcast.SubscriptionType
		switch streamProcessor.Stream {
		case config.StreamTypeFull:
			subscriptionType = broadcast.SubTypeFull
		case config.StreamTypeLite:
			subscriptionType = broadcast.SubTypeLite
		case config.StreamTypeDomainsOnly:
			subscriptionType = broadcast.SubTypeDomain
		}

		var c broadcast.CertProcessor
		switch streamProcessor.Type {
		case "nsq":
			log.Println("Initializing NSQ client...")
			c = broadcast.NewNSQClient(
				subscriptionType,
				addr,
				streamProcessor.Name,
				streamProcessor.Topic,
				cfg.General.BufferSizes.Websocket,
			)
		case "kafka":
			log.Println("Initializing Kafka client...")
			c = broadcast.NewKafkaClient(
				subscriptionType,
				addr,
				streamProcessor.Name,
				streamProcessor.Topic,
				string(streamProcessor.Compression),
				cfg.General.BufferSizes.Websocket,
			)
		default:
			log.Printf("Unknown stream processor type '%s' for %s. Skipping...\n", streamProcessor.Type, streamProcessor.Name)
		}

		log.Println(c)
		broadcast.ClientHandler.RegisterClient(c)
	}

	return cs, nil
}

// NewCertstreamFromConfigFile creates a new Certstream server from a config file.
func NewCertstreamFromConfigFile(configPath string) (*Certstream, error) {
	conf, err := config.ReadConfig(configPath)
	if err != nil {
		return nil, fmt.Errorf("error reading config: %w", err)
	}

	return NewCertstreamServer(conf)
}

// setupMetrics configures the webserver to handle prometheus metrics according to the config.
func (cs *Certstream) setupMetrics(webserver *web.Server) {
	if cs.config.Prometheus.Enabled {
		// If prometheus is enabled, and interface is either unconfigured or same as webserver config, use existing webserver
		if (cs.config.Prometheus.ListenAddr == "" || cs.config.Prometheus.ListenAddr == cs.config.Webserver.ListenAddr) &&
			(cs.config.Prometheus.ListenPort == 0 || cs.config.Prometheus.ListenPort == cs.config.Webserver.ListenPort) {
			log.Println("Starting prometheus server on same interface as webserver")
			webserver.RegisterPrometheus(cs.config.Prometheus.MetricsURL, metrics.Prometheus.Write)
		} else {
			log.Println("Starting prometheus server on new interface")

			cs.metricsServer = web.NewMetricsServer(
				cs.config.Prometheus.ListenAddr,
				cs.config.Prometheus.ListenPort,
				cs.config.Prometheus.CertPath,
				cs.config.Prometheus.CertKeyPath,
			)
			cs.metricsServer.RegisterPrometheus(cs.config.Prometheus.MetricsURL, metrics.Prometheus.Write)
		}
	}
}

// Start starts the webserver and the watcher.
// This is a blocking function that will run until the server is stopped.
func (cs *Certstream) Start() {
	log.Printf("Starting certstream-server-go v%s\n", config.Version)

	// handle signals in a separate goroutine
	signals := make(chan os.Signal, 1)
	signal.Notify(signals, syscall.SIGINT, syscall.SIGTERM)

	go signalHandler(signals, cs.Stop)

	// If there is no watcher initialized, create a new one
	if cs.watcher == nil {
		cs.watcher = certificatetransparency.NewWatcher()
	}

	// Start webserver and metrics server
	if cs.webserver == nil {
		log.Fatalln("Webserver not initialized! Exiting...")
	}

	go cs.webserver.Start()

	if cs.metricsServer != nil {
		go cs.metricsServer.Start()
	}

	// Start the watcher - this is a blocking function
	cs.watcher.Start()
}

// Stop stops the watcher and the webserver.
func (cs *Certstream) Stop() {
	if cs.watcher != nil {
		cs.watcher.Stop()
	}

	if cs.webserver != nil {
		cs.webserver.Stop()
	}

	if cs.metricsServer != nil {
		cs.metricsServer.Stop()
	}
}

// CreateIndexFile creates the index file for the certificate transparency logs.
// It gets only called when the CLI flag --create-index-file is set.
func (cs *Certstream) CreateIndexFile(outFile string) error {
	// If there is no watcher initialized, create a new one
	if cs.watcher == nil {
		cs.watcher = certificatetransparency.NewWatcher()
	}

	err := cs.watcher.CreateIndexFile(outFile)
	if err != nil {
		return fmt.Errorf("error creating index file: %w", err)
	}

	return nil
}

// signalHandler listens for signals in order to gracefully shut down the server.
// Executes the callback function when a signal is received.
func signalHandler(signals chan os.Signal, callback func()) {
	log.Println("Listening for signals...")

	sig := <-signals
	log.Printf("Received signal %v. Shutting down...\n", sig)
	callback()
	os.Exit(0)
}

package config

type BufferSizes struct {
	Websocket        int `mapstructure:"websocket"`
	CTLog            int `mapstructure:"ctlog"`
	BroadcastManager int `mapstructure:"broadcastmanager"`
	Dispatcher       int `mapstructure:"dispatcher"`
}

func (b *BufferSizes) Valid() bool {
	if b.Websocket <= 0 || b.CTLog <= 0 || b.BroadcastManager <= 0 || b.Dispatcher <= 0 {
		return false
	}

	return true
}

package config

import (
	"errors"
	"fmt"
	"log"
	"regexp"
	"strings"

	"github.com/spf13/viper"
)

var (
	// AppConfig holds the parsed configuration.
	AppConfig Config
	Version   = "1.10.1"

	ErrInvalidConfig = errors.New("invalid configuration")
	URLPathRegex     = regexp.MustCompile(`^(/[a-zA-Z0-9\-._]+)+$`)
	URLRegex         = regexp.MustCompile(`^https?://[a-zA-Z0-9\-._]+(:[0-9]+)?(/[a-zA-Z0-9\-._]+)*/?$`)
)

type Config struct {
	Webserver        Webserver
	Prometheus       Prometheus
	StreamProcessing []StreamProcessor `mapstructure:"stream_processing"`
	General          General
}

// ReadConfig reads the configuration using Viper and returns a filled Config struct.
// It also validates and stores the result in AppConfig.
func ReadConfig(configPath string) (Config, error) {
	v := initViper(configPath)
	return loadConfigFromViper(v)
}

// ValidateConfig validates the config file and returns an error if the config is invalid.
func ValidateConfig(configPath string) error {
	_, parseErr := ReadConfig(configPath)
	return parseErr
}

// initViper sets up the viper instance with defaults, config file and environment variable support.
// configPath is the path to the YAML config file (e.g. "config.yaml").
// Environment variables are mapped with the prefix "CERTSTREAM" and "_" as key delimiter.
// Example: CERTSTREAM_WEBSERVER_LISTEN_PORT overrides webserver.listen_port.
func initViper(configPath string) *viper.Viper {
	v := viper.NewWithOptions(viper.KeyDelimiter("."))

	// Defaults
	v.SetDefault("webserver.listen_addr", "0.0.0.0")
	v.SetDefault("webserver.listen_port", 8080)
	v.SetDefault("webserver.full_url", "/full-stream")
	v.SetDefault("webserver.lite_url", "/")
	v.SetDefault("webserver.domains_only_url", "/domains-only")
	v.SetDefault("webserver.real_ip", false)
	v.SetDefault("webserver.trusted_proxies", []string{})
	v.SetDefault("webserver.whitelist", []string{})
	v.SetDefault("webserver.compression_enabled", false)

	v.SetDefault("prometheus.enabled", false)
	v.SetDefault("prometheus.listen_addr", "0.0.0.0")
	v.SetDefault("prometheus.listen_port", 9090)
	v.SetDefault("prometheus.metrics_url", "/metrics")
	v.SetDefault("prometheus.expose_system_metrics", false)
	v.SetDefault("prometheus.real_ip", false)
	v.SetDefault("prometheus.trusted_proxies", []string{})
	v.SetDefault("prometheus.whitelist", []string{})

	v.SetDefault("general.disable_default_logs", false)
	v.SetDefault("general.buffer_sizes.websocket", 300)
	v.SetDefault("general.buffer_sizes.ctlog", 1000)
	v.SetDefault("general.buffer_sizes.broadcastmanager", 10000)
	v.SetDefault("general.drop_old_logs", true)
	v.SetDefault("general.recovery.enabled", false)
	v.SetDefault("general.recovery.ct_index_file", "./ct_index.json")

	if configPath != "" {
		v.SetConfigFile(configPath)
	} else {
		v.SetConfigName("config")
		v.AddConfigPath(".")
		v.AddConfigPath("/app/config")
	}

	v.SetConfigType("yaml")

	if err := v.ReadInConfig(); err != nil {
		var notFound viper.ConfigFileNotFoundError
		if errors.As(err, &notFound) {
			log.Println("No config file found, using defaults and environment variables only")
		} else {
			log.Fatalf("Error reading config file: %v", err)
		}
	} else {
		log.Printf("Using config file: %s\n", v.ConfigFileUsed())
	}

	// Environment variables
	// Prefix: CERTSTREAM  (e.g. CERTSTREAM_WEBSERVER_LISTEN_PORT)
	// Viper uses "." as key delimiter internally; environment variables use "_".
	// We replace "." with "_" when looking up env vars automatically.
	v.SetEnvPrefix("CERTSTREAM")
	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	v.AutomaticEnv()

	return v
}

// loadConfigFromViper unmarshals a viper instance into a Config struct, validates it
// and stores the result in AppConfig.
func loadConfigFromViper(v *viper.Viper) (Config, error) {
	var cfg Config

	if err := v.Unmarshal(&cfg); err != nil {
		return cfg, fmt.Errorf("failed to unmarshal config: %w", err)
	}

	if !validateConfig(&cfg) {
		return cfg, ErrInvalidConfig
	}

	AppConfig = cfg

	return cfg, nil
}

// validateConfig validates the config values and sets defaults for missing values.
func validateConfig(config *Config) bool {
	// Still matches invalid IP addresses but good enough for detecting completely wrong formats

	// Check webserver config
	if !config.Webserver.Valid() {
		return false
	}

	if !config.Prometheus.Valid() {
		return false
	}

	for _, processor := range config.StreamProcessing {
		if !processor.Valid() {
			return false
		}
	}

	if !config.General.Valid() {
		return false
	}

	return true
}

package config

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/spf13/viper"
)

// minimalValidYAML is the smallest config that passes validateConfig.
// It only sets the fields that validateConfig strictly requires, leaving
// everything else at its viper default so we can assert default values.
const (
	minimalValidYAML = `
webserver:
  listen_addr: "0.0.0.0"
  listen_port: 8080
  full_url: "/full-stream"
  lite_url: "/"
  domains_only_url: "/domains-only"
`
	domainsOnlyURL = "/domains-only"
	fullStreamURL  = "/full-stream"
)

// writeConfigFile writes content to a temporary YAML file and returns its path.
func writeConfigFile(t *testing.T, content string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "config.yaml")
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatalf("failed to write temp config file: %v", err)
	}
	return path
}

// TestWebserverDefaults uses a config file that only sets required
// webserver fields so that optional keys still reflect their defaults.
func TestWebserverDefaults(t *testing.T) {
	// Only listen_addr and listen_port are set. Remaining keys should be default.
	yaml := `
webserver:
  listen_addr: "0.0.0.0"
  listen_port: 8080
`
	configPath := writeConfigFile(t, yaml)
	v := initViper(configPath)

	cases := []struct {
		key  string
		want any
	}{
		{"webserver.full_url", fullStreamURL},
		{"webserver.lite_url", "/"},
		{"webserver.domains_only_url", domainsOnlyURL},
		{"webserver.real_ip", false},
		{"webserver.compression_enabled", false},
	}

	for _, testcase := range cases {
		switch want := testcase.want.(type) {
		case string:
			if got := v.GetString(testcase.key); got != want {
				t.Errorf("key %s: want %q, got %q", testcase.key, want, got)
			}
		case bool:
			if got := v.GetBool(testcase.key); got != want {
				t.Errorf("key %s: want %v, got %v", testcase.key, want, got)
			}
		}
	}
}

// TestPrometheusDefaults uses a config file that only sets required
// webserver fields so that optional keys still reflect their defaults.
func TestPrometheusDefaults(t *testing.T) {
	// No prometheus section in the config – all keys should come from defaults.
	configPath := writeConfigFile(t, minimalValidYAML)
	v := initViper(configPath)

	if got := v.GetBool("prometheus.enabled"); got != false {
		t.Errorf("prometheus.enabled: want false, got %v", got)
	}
	if got := v.GetString("prometheus.listen_addr"); got != "0.0.0.0" {
		t.Errorf("prometheus.listen_addr: want '0.0.0.0', got %q", got)
	}
	if got := v.GetInt("prometheus.listen_port"); got != 9090 {
		t.Errorf("prometheus.listen_port: want 9090, got %d", got)
	}
	if got := v.GetString("prometheus.metrics_url"); got != "/metrics" {
		t.Errorf("prometheus.metrics_url: want '/metrics', got %q", got)
	}
	if got := v.GetBool("prometheus.expose_system_metrics"); got != false {
		t.Errorf("prometheus.expose_system_metrics: want false, got %v", got)
	}
	if got := v.GetBool("prometheus.real_ip"); got != false {
		t.Errorf("prometheus.real_ip: want false, got %v", got)
	}
}

// TestGeneralDefaults uses an empty string as configPath.
// It tests whether the defaults are properly configured.
func TestGeneralDefaults(t *testing.T) {
	// No general section in the config – all keys should come from defaults.

	v := initViper("")

	if got := v.GetBool("general.disable_default_logs"); got != false {
		t.Errorf("general.disable_default_logs: want false, got %v", got)
	}
	if got := v.GetInt("general.buffer_sizes.websocket"); got != 300 {
		t.Errorf("general.buffer_sizes.websocket: want 300, got %d", got)
	}
	if got := v.GetInt("general.buffer_sizes.ctlog"); got != 1000 {
		t.Errorf("general.buffer_sizes.ctlog: want 1000, got %d", got)
	}
	if got := v.GetInt("general.buffer_sizes.broadcastmanager"); got != 10000 {
		t.Errorf("general.buffer_sizes.broadcastmanager: want 10000, got %d", got)
	}
	if got := v.GetBool("general.drop_old_logs"); got != true {
		t.Errorf("general.drop_old_logs: want true, got %v", got)
	}
	if got := v.GetBool("general.recovery.enabled"); got != false {
		t.Errorf("general.recovery.enabled: want false, got %v", got)
	}
	if got := v.GetString("general.recovery.ct_index_file"); got != "./ct_index.json" {
		t.Errorf("general.recovery.ct_index_file: want './ct_index.json', got %q", got)
	}
}

// TestConfigFileOverridesDefaults verifies that values from the config file override
// the defaults, while keys absent from the file still return their default values.
func TestConfigFileOverridesDefaults(t *testing.T) {
	yaml := `
webserver:
  listen_addr: "127.0.0.1"
  listen_port: 9999
`
	configPath := writeConfigFile(t, yaml)
	v := initViper(configPath)

	if got := v.GetString("webserver.listen_addr"); got != "127.0.0.1" {
		t.Errorf("listen_addr: want '127.0.0.1', got %q", got)
	}
	if got := v.GetInt("webserver.listen_port"); got != 9999 {
		t.Errorf("listen_port: want 9999, got %d", got)
	}

	// Keys absent from the file must still return the registered defaults.
	if got := v.GetString("webserver.full_url"); got != fullStreamURL {
		t.Errorf("full_url (default): want '%q', got %q", fullStreamURL, got)
	}
}

// TestEnvOverridesDefaults verifies that environment variables
// take precedence over defaults when no config file is provided.
func TestEnvOverridesDefaults(t *testing.T) {
	t.Setenv("CERTSTREAM_WEBSERVER_LISTEN_PORT", "6543")

	configPath := writeConfigFile(t, minimalValidYAML)
	v := initViper(configPath)

	if got := v.GetInt("webserver.listen_port"); got != 6543 {
		t.Errorf("listen_port via env: want 6543, got %d", got)
	}
}

// TestEnvOverridesConfigFile verifies that environment variables
// take precedence over config file values.
func TestEnvOverridesConfigFile(t *testing.T) {
	configPath := writeConfigFile(t, minimalValidYAML)
