package config

import (
	"log"
	"strings"
)

type LogConfig struct {
	Operator    string `mapstructure:"operator"`
	URL         string `mapstructure:"url"`
	Description string `mapstructure:"description"`
}

type General struct {
	// DisableDefaultLogs indicates whether the default logs used in Google Chrome and provided by Google should be disabled.
	DisableDefaultLogs bool `mapstructure:"disable_default_logs"`
	// AdditionalLogs contains additional logs provided by the user that can be used in addition to the default logs.
	AdditionalLogs      []LogConfig `mapstructure:"additional_logs"`
	AdditionalTiledLogs []LogConfig `mapstructure:"additional_tiled_logs"`
	ExcludedLogs        []LogConfig `mapstructure:"excluded_logs"`
	// BufferSizes contains the buffer sizes for the different components of the server. They usually don't need any adjustments.
	BufferSizes BufferSizes `mapstructure:"buffer_sizes"`
	// DropOldLogs indicates whether downloading CT-Logs should start at the latest index (true) or should from the beginning (false).
	DropOldLogs *bool `mapstructure:"drop_old_logs"`
	Recovery    struct {
		Enabled     bool   `mapstructure:"enabled"`
		CTIndexFile string `mapstructure:"ct_index_file"`
	} `mapstructure:"recovery"`
}

func (g *General) Valid() bool {
	var validLogs, validTiledLogs, validExcludedLogs []LogConfig

	if len(g.AdditionalLogs) > 0 {
		for _, ctLog := range g.AdditionalLogs {
			if !URLRegex.MatchString(ctLog.URL) {
				log.Println("Ignoring invalid additional log URL: ", ctLog.URL)
				continue
			}

			validLogs = append(validLogs, ctLog)
		}
	}

	if len(g.AdditionalTiledLogs) > 0 {
		for _, ctLog := range g.AdditionalTiledLogs {
			if !URLRegex.MatchString(ctLog.URL) {
				log.Println("Ignoring invalid additional log URL: ", ctLog.URL)
				continue
			}

			validTiledLogs = append(validTiledLogs, ctLog)
		}
	}

	if len(g.ExcludedLogs) > 0 {
		for _, excludedLog := range g.ExcludedLogs {
			excludedLog.Operator = strings.TrimSpace(excludedLog.Operator)
			excludedLog.URL = strings.TrimSpace(excludedLog.URL)

			if excludedLog.Operator == "" && excludedLog.URL == "" {
				log.Println("Ignoring empty excluded_logs entry. Set operator and/or url.")
				continue
			}

			if excludedLog.URL != "" && !URLRegex.MatchString(excludedLog.URL) {
				log.Println("Ignoring invalid excluded log URL: ", excludedLog.URL)
				continue
			}

			validExcludedLogs = append(validExcludedLogs, excludedLog)
		}
	}

	g.AdditionalLogs = validLogs
	g.AdditionalTiledLogs = validTiledLogs
	g.ExcludedLogs = validExcludedLogs

	if len(g.AdditionalLogs) == 0 && len(g.AdditionalTiledLogs) == 0 && g.DisableDefaultLogs {
		log.Fatalln("Default logs are disabled, but no additional logs are configured. Please add at least one log to the config or enable default logs.")
	}

	if g.BufferSizes.Websocket <= 0 {
		g.BufferSizes.Websocket = 300
	}

	if g.BufferSizes.CTLog <= 0 {
		g.BufferSizes.CTLog = 1000
	}

	// For backward compatibility, copy value from deprecated BroadcastManager field
	if g.BufferSizes.BroadcastManager != 0 {
		g.BufferSizes.Dispatcher = g.BufferSizes.BroadcastManager
	}

	if g.BufferSizes.Dispatcher <= 0 {
		g.BufferSizes.Dispatcher = 10000
	}

	// If the cleanup flag is not set, default to true
	if g.DropOldLogs == nil {
		log.Println("drop_old_logs is not set, defaulting to true")

		defaultCleanup := true
		g.DropOldLogs = &defaultCleanup
	}

	if g.Recovery.Enabled && g.Recovery.CTIndexFile == "" {
		log.Println("Recovery enabled but no index file specified. Defaulting to ./ct_index.json")

		g.Recovery.CTIndexFile = "./ct_index.json"
	}

	return true
}

package config

import (
	"log"
	"net"
)

type Prometheus struct {
	ServerConfig `mapstructure:",squash"`

	Enabled             bool   `mapstructure:"enabled"`
	MetricsURL          string `mapstructure:"metrics_url"`
	ExposeSystemMetrics bool   `mapstructure:"expose_system_metrics"`
}

func (p *Prometheus) Valid() bool {
	if !p.Enabled {
		return true
	}

	if p.ListenAddr == "" || net.ParseIP(p.ListenAddr) == nil {
		log.Fatalln("Metrics export IP is not a valid IP")
		return false
	}

	if p.ListenPort == 0 {
		log.Fatalln("Metrics export port is not set")
		return false
	}

	if p.Whitelist == nil {
		p.Whitelist = []string{}
	}

	// Check if IPs in whitelist match pattern
	for _, ip := range p.Whitelist {
		if net.ParseIP(ip) != nil {
			continue
		}

		// Provided entry is not an IP, check if it's a CIDR range
		_, _, err := net.ParseCIDR(ip)
		if err != nil {
			log.Fatalln("Invalid IP in metrics whitelist: ", ip)
			return false
		}
	}

	for _, ip := range p.TrustedProxies {
		if net.ParseIP(ip) != nil {
			continue
		}

		_, _, err := net.ParseCIDR(ip)
		if err != nil {
			log.Fatalln("Invalid IP/CIDR in prometheus trusted_proxies: ", ip)
			return false
		}
	}

	return true
}

package config

import (
	"log"
	"net"
)

// StreamProcessorType represents the type of stream processing tool to use.
// Supported types are "kafka" and "nqs".
type StreamProcessorType string

const (
	StreamProcessorTypeKafka StreamProcessorType = "kafka"
	StreamProcessorTypeNQS   StreamProcessorType = "nqs"
)

// StreamType represents the type of stream to process.
// Supported types are "full", "lite", and "domains-only".
type StreamType string

const (
	StreamTypeFull        StreamType = "full"
	StreamTypeLite        StreamType = "lite"
	StreamTypeDomainsOnly StreamType = "domains-only"
)

// Compression represents the compression type for stream processing.
type Compression string

const (
	CompressionNone    Compression = "none"
	CompressionGzip    Compression = "gzip"
	CompressionSnappy  Compression = "snappy"
	CompressionZstd    Compression = "zstd"
	CompressionLz4     Compression = "lz4"
	CompressionDeflate Compression = "deflate"
)

func (c Compression) setDefaults() {
	if c == "" {
		c = CompressionNone
	}
}

// Valid returns true if the compression type is valid.
func (c Compression) Valid() bool {
	c.setDefaults()

	switch c {
	case CompressionNone, CompressionGzip, CompressionSnappy, CompressionZstd, CompressionLz4:
		return true
	default:
		return false
	}
}

// SupportedBy returns true if the compression type is supported by the stream processing tool.
func (c Compression) SupportedBy(t StreamProcessorType) bool {
	if c == CompressionNone {
		return true
	}

	switch t {
	case StreamProcessorTypeKafka:
		return c == CompressionNone || c == CompressionGzip || c == CompressionSnappy || c == CompressionZstd || c == CompressionLz4
	case StreamProcessorTypeNQS:
		return c == CompressionNone || c == CompressionDeflate || c == CompressionSnappy
	default:
		return false
	}
}

type StreamProcessor struct {
	Name        string              `mapstructure:"name"`
	Type        StreamProcessorType `mapstructure:"type"`
	Stream      StreamType          `mapstructure:"stream"`
	Enabled     *bool               `mapstructure:"enabled"`
	ServerAddr  string              `mapstructure:"server_addr"`
	ServerPort  int                 `mapstructure:"server_port"`
	Topic       string              `mapstructure:"topic"`
	Compression Compression         `mapstructure:"compression"`
}

func (s *StreamProcessor) setDefaults() {
	if s.Enabled == nil {
		enabled := true
		s.Enabled = &enabled
	}
	if s.Compression == "" {
		s.Compression = CompressionNone
	}
}

func (s *StreamProcessor) Valid() bool {
	s.setDefaults()

	ip := net.ParseIP(s.ServerAddr)
	if ip == nil {
		log.Fatalln("Invalid IP for stream processor:", s.ServerAddr)
		return false
	}

	if s.ServerPort <= 0 {
		log.Fatalln("Invalid server port for stream processor:", s.ServerPort)
		return false
	}

	switch s.Type {
	case StreamProcessorTypeKafka, StreamProcessorTypeNQS:
	default:
		log.Fatalf("Invalid stream processor type '%s' for name '%s'\n", s.Type, s.Name)
		return false
	}

	if s.Topic == "" {
		log.Println("Found stream processing config with empty topic - using \"certstream\" as topic for name", s.Name)
		s.Topic = "certstream"
	}

	// Check that the compression type is generally valid
	if !s.Compression.Valid() {
		log.Fatalf("Invalid compression '%s' for stream processor '%s'\n", s.Compression, s.Name)
		return false
	}

	// Check that the compression type is supported by the stream processing tool
	if !s.Compression.SupportedBy(s.Type) {
		log.Fatalf("Compression '%s' is not supported by stream processor type '%s' for name '%s'\n", s.Compression, s.Type, s.Name)
		return false
	}

	return true
}

package config

import (
	"log"
	"net"
)

type Webserver struct {
	ServerConfig `mapstructure:",squash"`

	FullURL            string `mapstructure:"full_url"`
	LiteURL            string `mapstructure:"lite_url"`
	DomainsOnlyURL     string `mapstructure:"domains_only_url"`
	CompressionEnabled bool   `mapstructure:"compression_enabled"`
}

func (w *Webserver) Valid() bool {
	// Still matches invalid IP addresses but good enough for detecting completely wrong formats

	if w.ListenAddr == "" || net.ParseIP(w.ListenAddr) == nil {
		log.Fatalln("Webhook listen IP is not a valid IP: ", w.ListenAddr)
		return false
	}

	if w.ListenPort == 0 {
		log.Fatalln("Webhook listen port is not set")
		return false
	}

	if w.FullURL == "" || !URLPathRegex.MatchString(w.FullURL) {
		log.Println("Webhook full URL is not set or does not match pattern '/...'")

		w.FullURL = "/full-stream"
	}

	if w.LiteURL == "" || !URLPathRegex.MatchString(w.FullURL) {
		log.Println("Webhook lite URL is not set or does not match pattern '/...'")

		w.LiteURL = "/"
	}

	if w.DomainsOnlyURL == "" || !URLPathRegex.MatchString(w.DomainsOnlyURL) {
		log.Println("Webhook domains only URL is not set or does not match pattern '/...'")

		w.FullURL = "/domains-only"
	}

	if w.FullURL == w.LiteURL {
		log.Fatalln("Webhook full URL is the same as lite URL - please fix the config!")
	}

	if w.DomainsOnlyURL == "" {
		w.FullURL = "/domains-only"
	}

	for _, ip := range w.TrustedProxies {
		if net.ParseIP(ip) != nil {
			continue
		}

		_, _, err := net.ParseCIDR(ip)
		if err != nil {
			log.Fatalln("Invalid IP/CIDR in webserver trusted_proxies: ", ip)
			return false
		}
	}

	return true
}

package metrics

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"maps"
	"os"
	"sync"
	"time"
)

type (
	// OperatorLogs is a map of operator names to a list of CT log urls, operated by said operator.
	OperatorLogs map[string][]string
	// OperatorMetric is a map of CT log urls to the number of certs processed by said log.
	OperatorMetric map[string]int64
	// CTMetrics is a map of operator names to a map of CT log urls to the number of certs processed by said log.
	CTMetrics map[string]OperatorMetric
	// CTCertIndex is a map of CT log urls to the last processed certficate index on the said log.
	CTCertIndex map[string]uint64
)

var (
	ProcessedCerts    int64
	ProcessedPrecerts int64
	Metrics           = LogMetrics{metrics: make(CTMetrics), index: make(CTCertIndex)}
)

// LogMetrics is a struct that holds a map of metrics for each CT log grouped by operator.
// Metrics can be accessed and written concurrently through the Get, Set and Inc methods.
type LogMetrics struct {
	mutex   sync.RWMutex
	metrics CTMetrics
	index   CTCertIndex
}

// GetCTMetrics returns a copy of the internal metrics map.
func (m *LogMetrics) GetCTMetrics() CTMetrics {
	m.mutex.RLock()
	defer m.mutex.RUnlock()

	// Using maps.copy() does not copy the nested maps.
	// That leads to an issue where simultaneous reads and writes to the same nested map can happen.
	copiedMap := make(CTMetrics)
	for operator, urls := range m.metrics {
		copiedMap[operator] = make(OperatorMetric)
		for url, count := range urls {
			//nolint:modernize
			copiedMap[operator][url] = count
		}
	}

	return copiedMap
}

// OperatorLogMapping returns a map of operator names to a list of CT logs.
func (m *LogMetrics) OperatorLogMapping() OperatorLogs {
	m.mutex.RLock()
	defer m.mutex.RUnlock()

	logOperators := make(map[string][]string, len(m.metrics))

	for operator, urls := range m.metrics {
		urlList := make([]string, len(urls))
		counter := 0

		for url := range urls {
			urlList[counter] = url
			counter++
		}

		logOperators[operator] = urlList
	}

	return logOperators
}

// Init initializes the internal metrics map with the given operator names and CT log urls if it doesn't exist yet.
func (m *LogMetrics) Init(operator, url string) {
	m.mutex.Lock()
	defer m.mutex.Unlock()

	// if the operator does not exist, create a new entry
	if _, ok := m.metrics[operator]; !ok {
		m.metrics[operator] = make(OperatorMetric)
	}

	// if the operator exists but the url does not, create a new entry
	if _, ok := m.metrics[operator][url]; !ok {
		m.metrics[operator][url] = 0
	}

	// if url index does not exist, create a new entry
	if _, ok := m.index[url]; !ok {
		m.index[url] = 0
	}

	// Register the metric for this operator and url with Prometheus
	Prometheus.RegisterLog(operator, url)
}

// Get the metric for a given operator and ct url.
func (m *LogMetrics) Get(operator, url string) int64 {
	// Despite this being a getter, we still need to fully lock the mutex because we might modify the map if the requested operator does not exist.
	m.mutex.Lock()
	defer m.mutex.Unlock()

	if _, ok := m.metrics[operator]; !ok {
		m.metrics[operator] = make(OperatorMetric)
	}

	return m.metrics[operator][url]
}

// Set the metric for a given operator and ct url.
func (m *LogMetrics) Set(operator, url string, value int64) {
	m.mutex.Lock()
	defer m.mutex.Unlock()

	if _, ok := m.metrics[operator]; !ok {
		m.metrics[operator] = make(OperatorMetric)
	}

	m.metrics[operator][url] = value
}

// Inc the metric for a given operator and ct url.
func (m *LogMetrics) Inc(operator, url string, index uint64) {
	m.mutex.Lock()
	defer m.mutex.Unlock()

	if _, ok := m.metrics[operator]; !ok {
		m.metrics[operator] = make(OperatorMetric)
	}

	m.metrics[operator][url]++

	m.index[url] = index
}

// GetAllCTIndexes returns a copy of the internal CT index map.
func (m *LogMetrics) GetAllCTIndexes() CTCertIndex {
	m.mutex.RLock()
	defer m.mutex.RUnlock()

	// make a copy of the index and return it, since map is a reference type
	copyOfIndex := make(CTCertIndex)
	maps.Copy(copyOfIndex, m.index)

	return copyOfIndex
}

// GetCTIndex returns the last cert index processed for a given CT url.
func (m *LogMetrics) GetCTIndex(url string) uint64 {
	m.mutex.RLock()
	defer m.mutex.RUnlock()

	index, ok := m.index[url]
	if !ok {
		return 0
	}

	return index
}

// SetCTIndex sets the index for a given CT url.
func (m *LogMetrics) SetCTIndex(url string, index uint64) {
	m.mutex.Lock()
	defer m.mutex.Unlock()

	log.Printf("Setting CT index for %s to %d\n", url, index)
	m.index[url] = index
}

// LoadCTIndex loads the last cert index processed for each CT url if it exists.
func (m *LogMetrics) LoadCTIndex(ctIndexFilePath string) {
	log.Println("Loading CT indexes from file: ", ctIndexFilePath)

	m.mutex.Lock()
	defer m.mutex.Unlock()

	bytes, readErr := os.ReadFile(ctIndexFilePath)
	if readErr != nil {
		// Create the file if it doesn't exist
		if os.IsNotExist(readErr) {
			err := m.createCTIndexFile(ctIndexFilePath)
			if err != nil {
				log.Printf("Error creating CT index file: '%s'\n", ctIndexFilePath)
				log.Panicln(err)
			}

			bytes = []byte("{}")
		} else {
			// If the file exists, but we can't read it, log the error and panic
			log.Panicln(readErr)
		}
	}

	m.index = make(CTCertIndex)

	if len(bytes) == 0 || string(bytes) == "" {
		log.Panicln("CT index file is empty!")
		return
	}

	jerr := json.Unmarshal(bytes, &m.index)
	if jerr != nil {
		log.Printf("Error unmarshalling CT index file: '%s'\n", ctIndexFilePath)
		log.Panicln(jerr)
	}

	log.Println("Successfully loaded saved CT indexes")
}

func (m *LogMetrics) createCTIndexFile(ctIndexFilePath string) error {
	log.Printf("Specified CT index file does not exist, creating now: '%s'\n", ctIndexFilePath)

	file, createErr := os.Create(ctIndexFilePath)
	if createErr != nil {
		log.Printf("Error creating CT index file: '%s'\n", ctIndexFilePath)
		log.Panicln(createErr)
	}
	defer file.Close()

	if m.index == nil {
		m.index = make(CTCertIndex)
	}

	bytes, marshalErr := json.Marshal(m.index)
	if marshalErr != nil {
		return fmt.Errorf("failed to marshal index data: %w", marshalErr)
	}

	_, writeErr := file.Write(bytes)
	if writeErr != nil {
		log.Printf("Error writing to CT index file: '%s'\n", ctIndexFilePath)
		log.Panicln(writeErr)
	}

	return nil
}

// SaveCertIndexesAtInterval saves the index of CTLogs at given intervals.
// We first create a temp file and write the index data to it. Only then do we move the temp file to the actual
// permanent index file. This prevents the last good index file from being clobbered if the program was shutdown/killed
// in-between the write operation.
func (m *LogMetrics) SaveCertIndexesAtInterval(ctx context.Context, interval time.Duration, ctIndexFilePath string) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			if err := m.SaveCertIndexes(ctIndexFilePath); err != nil {
				log.Printf("Error saving CT indexes at '%s': %s\n", ctIndexFilePath, err)
			}
		}
	}
}

// SaveCertIndexes saves the index of CTLogs to a file.
func (m *LogMetrics) SaveCertIndexes(ctIndexFilePath string) error {
	tempFilePath := ctIndexFilePath + ".tmp"

	// Get the index data
	ctIndex := m.GetAllCTIndexes()

	bytes, cerr := json.MarshalIndent(ctIndex, "", " ")
	if cerr != nil {
		log.Panic(cerr)
	}

	// Store index data in a temp file
	err := storeTempFile(tempFilePath, bytes)
	if err != nil {
		return err
	}

	// Atomically move the temp file to the permanent file
	renameErr := os.Rename(tempFilePath, ctIndexFilePath)
	if renameErr != nil {
		return fmt.Errorf("could not rename CT index temp file: %w", renameErr)
	}

	return nil
}

// storeTempFile stores the passed data in the tempFilePath.
func storeTempFile(tempFilePath string, bytes []byte) error {
	// Save data to a temporary file first
	file, openErr := os.OpenFile(tempFilePath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
	if openErr != nil {
		return fmt.Errorf("could not save CT index to temporary file: %w", openErr)
	}
	defer file.Close()

	truncateErr := file.Truncate(0)
	if truncateErr != nil {
		return fmt.Errorf("could not save CT index to temporary file: %w", truncateErr)
	}

	// TODO: check for short writes
	_, writeErr := file.Write(bytes)
	if writeErr != nil {
		return fmt.Errorf("could not save CT index to temporary file: %w", writeErr)
	}

	syncErr := file.Sync()
	if syncErr != nil {
		return fmt.Errorf("could not save CT index to temporary file: %w", syncErr)
	}

	return nil
}

// GetProcessedCerts returns the total number of processed certificates.
func GetProcessedCerts() int64 {
	return ProcessedCerts
}

// GetProcessedPrecerts returns the total number of processed precertificates.
func GetProcessedPrecerts() int64 {
	return ProcessedPrecerts
}

// GetCertMetrics returns a copy of the internal metrics map.
func GetCertMetrics() CTMetrics {
	return Metrics.GetCTMetrics()
}

// GetLogOperators returns a map of operator names to a list of CT logs.
func GetLogOperators() map[string][]string {
	return Metrics.OperatorLogMapping()
}

