func TestLoadCTIndex_LoadsEmptyJSONFile(t *testing.T) {
	m := &LogMetrics{metrics: make(CTMetrics), index: make(CTCertIndex)}
	path := filepath.Join(t.TempDir(), "ct_index.json")

